h1&gt;\r\n			- BOOK 1\r\n			- BOOK 2\r\n			- BOOK 3\r\n		&lt;/aside&gt;\r\n		\r\n		&lt;footer&gt;\r\n			このサイトは @motoki によって運営されています。\r\n		&lt;/footer&gt;\r\n		\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','HTML5 #13(ドットインストール)','','inherit','closed','closed','','168-revision-v1','','','2017-11-29 19:13:04','2017-11-29 10:13:04','',168,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/168-revision-v1/',0,'revision','',0),(179,1,'2017-11-29 19:31:31','2017-11-29 10:31:31','#14 aタグでリンクを設定しよう\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_html_v3/31614\">https://dotinstall.com/lessons/basic_html_v3/31614</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/01_html/14/\">http://www.tmotoki.net/static/dot_install/01_html/14/</a>\r\n\r\n■メモ\r\n\r\na:リンク\r\n\r\nhrefでurlを指定\r\ntargetでどこに開くか設定できる\r\n#(パウンド記号)にIDをつけてリンクすると、\r\nページ内リンクできる\r\n\r\ntargetの種類\r\n---\r\nblank 新しいWindow表示\r\n_self 今のWindowに表示\r\n_top フレーム分割を解除して今のWindowに表示\r\n_parent 分割を一段だけ解除して親フレームに表示\r\n<pre class=\"lang:xhtml decode:true \">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;はじめてのHTML&lt;/title&gt;\r\n		&lt;link rel=\"shortcut icon\" href=\"favicon.ico\"&gt;\r\n		&lt;!--link rel=\"stylesheet\" href=\"mystyles.css\"--&gt;\r\n	&lt;/head&gt;\r\n	&lt;body&gt;\r\n	\r\n	&lt;!--\r\n		a:リンク\r\n		hrefでurlを指定\r\n		targetでどこに開くか設定できる\r\n		#(パウンド記号)にIDをつけてリンクすると、\r\n		ページ内リンクできる\r\n	--&gt;\r\n	\r\n		&lt;header&gt;\r\n			&lt;h1&gt;&lt;a href=\"more.html\"&gt;おいしいごはん！&lt;/a&gt;&lt;/h1&gt;\r\n			&lt;nav&gt;\r\n			- ホーム =&gt; &lt;a href=\"more.html\" target=\"_blank\"&gt;もっとみる&lt;/a&gt; ⇒ &lt;a href=\"#stuff\"&gt;材料&lt;/a&gt;\r\n			- このサイトについて\r\n			- プロフィール\r\n			&lt;/nav&gt;\r\n		&lt;/header&gt;\r\n		\r\n		&lt;section&gt;\r\n			&lt;h1&gt;今日のおいしいごはん&lt;/h1&gt;\r\n			&lt;article&gt;\r\n				&lt;h1&gt;おいしいごはん #12&lt;/h1&gt;\r\n				&lt;p&gt;至高のTKG&lt;/p&gt;\r\n				&lt;h2 id=\"stuff\"&gt;材料&lt;/h2&gt;\r\n				&lt;ul&gt;\r\n					&lt;li&gt;卵&lt;/li&gt;\r\n					&lt;li&gt;しょうゆ&lt;/li&gt;\r\n					&lt;li&gt;ごはん&lt;/li&gt;\r\n				&lt;/ul&gt;\r\n				&lt;h2&gt;手順&lt;/h2&gt;\r\n				&lt;ol&gt;\r\n					&lt;li&gt;まぜる&lt;/li&gt;\r\n					&lt;li&gt;かける&lt;/li&gt;\r\n				&lt;/ol&gt;\r\n				&lt;h2&gt;定義&lt;/h2&gt;\r\n				&lt;dl&gt;\r\n					&lt;dt&gt;TKG&lt;/dt&gt;\r\n					&lt;dd&gt;TAMAGO KAKE GOHAN&lt;/dd&gt;\r\n				&lt;/dl&gt;\r\n			&lt;/article&gt;\r\n		&lt;/section&gt;\r\n		\r\n		&lt;section&gt;\r\n			&lt;h1&gt;新着のおいしいごはん&lt;/h1&gt;\r\n			&lt;article&gt;\r\n				&lt;h1&gt;おいしいごはん #32&lt;/h1&gt;\r\n				はもしゃぶ\r\n			&lt;/article&gt;\r\n			&lt;article&gt;\r\n				&lt;h1&gt;おいしいごはん #31&lt;/h1&gt;\r\n				スリランカカレー\r\n			&lt;/article&gt;\r\n		&lt;/section&gt;\r\n		\r\n		&lt;aside&gt;\r\n			&lt;h1&gt;おすすめレシピ本&lt;/h1&gt;\r\n			- BOOK 1\r\n			- BOOK 2\r\n			- BOOK 3\r\n		&lt;/aside&gt;\r\n		\r\n		&lt;footer&gt;\r\n			このサイトは @motoki によって運営されています。\r\n		&lt;/footer&gt;\r\n		\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','HTML5 #14(ドットインストール)','','publish','open','open','','html5-14%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:46:51','2017-12-27 18:46:51','',0,'http://www.tmotoki.net/?p=179',0,'post','',0),(180,1,'2017-11-29 19:31:31','2017-11-29 10:31:31','#14 aタグでリンクを設定しよう\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_html_v3/31614\">https://dotinstall.com/lessons/basic_html_v3/31614</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/01_html/14/\">http://www.tmotoki.net/static/dot_install/01_html/14/</a>\r\n\r\n■メモ\r\n\r\na:リンク\r\n\r\nhrefでurlを指定\r\ntargetでどこに開くか設定できる\r\n#(パウンド記号)にIDをつけてリンクすると、\r\nページ内リンクできる\r\n\r\ntargetの種類\r\n---\r\nblank 新しいWindow表示\r\n_self 今のWindowに表示\r\n_top フレーム分割を解除して今のWindowに表示\r\n_parent 分割を一段だけ解除して親フレームに表示\r\n<pre class=\"lang:xhtml decode:true \">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;は