=\"http://yahoo.com\"\n			 title=\"yahoo\" class=\"link search\"&gt;\n				Yahoo\n			&lt;/a&gt;\n		&lt;/p&gt;\n	&lt;/body&gt;\n&lt;/html&gt;\n</pre>\n<pre class=\"lang:css decode:true\" title=\"CSS\">/*\n 属性セレクタ\n*/\n\n	/* 特定の属性があるもの */\n	a[target] { color:skyblue; }\n\n	/* 特定の属性が特定の値 */\n	a[href=\"http://google.com\"] { color:Crimson; }\n\n	/* 特定の属性が特定の値が含まれる */\n	a[class~=\"search\"] { color:orange; }\n</pre>\n&nbsp;\n\n&nbsp;','CSS #05(ドットインストール)','','inherit','closed','closed','','241-autosave-v1','','','2017-12-07 11:11:18','2017-12-07 02:11:18','',241,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/241-autosave-v1/',0,'revision','',0),(245,1,'2017-12-07 11:12:54','2017-12-07 02:12:54','#05 属性セレクタを使ってみよう\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31705\">https://dotinstall.com/lessons/basic_css_v3/31705</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/05/\">http://www.tmotoki.net/static/dot_install/02_css/05/</a>\r\n\r\n■メモ\r\n属性やその値によって、スタイルを切り分ける\r\ninputタグのtype毎に設定したりすることもある。\r\n\r\n今回はAタグに対して。\r\nタグに対する属性指定は[]。\r\n完全一致の場合は「属性=値」。\r\n含む値で条件設定する場合は「属性~=値」(チルダイコール)。\r\n<pre class=\"lang:css decode:true\" title=\"CSS\">/*\r\n 属性セレクタ\r\n*/\r\n\r\n	/* 特定の属性があるもの */\r\n	a[target] { color:skyblue; }\r\n\r\n	/* 特定の属性が特定の値 */\r\n	a[href=\"http://google.com\"] { color:Crimson; }\r\n\r\n	/* 特定の属性が特定の値が含まれる */\r\n	a[class~=\"search\"] { color:orange; }</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;p&gt;\r\n			1.&lt;a href=\"http://yahoo.com\"\r\n			 target=\"_self\" title=\"yahoo\"&gt;\r\n				Yahoo\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		&lt;p&gt;\r\n			2.&lt;a href=\"http://google.com\" &gt;\r\n				Google\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		&lt;p&gt;\r\n			3.&lt;a href=\"http://yahoo.com\"\r\n			 title=\"yahoo\" class=\"link search\"&gt;\r\n				Yahoo\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;</pre>\r\n&nbsp;\r\n\r\n&nbsp;','CSS #05(ドットインストール)','','inherit','closed','closed','','241-revision-v1','','','2017-12-07 11:12:54','2017-12-07 02:12:54','',241,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/241-revision-v1/',0,'revision','',0),(246,1,'2017-12-08 10:26:20','2017-12-08 01:26:20','デザイナー向けのセミナーで、\r\n正直あまり期待してなかったのですが、\r\nすごく良い内容のセミナーでした。\r\n\r\nWebフロントエンドの技術とサーバサイドの技術が、\r\nスマホアプリと融合して、\r\n今後もっと簡単にマルチプラットフォームが実現できていけそうでした。\r\n\r\n自分の目指す方向性が間違ってなさそうな気がして、\r\nこのまま進んでいきたいと思いまいした。\r\n\r\nというわけで、来週くらいまでに、\r\nAndroidアプリでこのサイトを表示するやつを作ってみたいと思います。\r\n（できたら）\r\nほんとはiOSアプリを作りたいのですが、\r\nMac持ってないので。。ああそろそろほしくなってきた。。','デザイナー向けWebとスマホアプリの話','','publish','open','open','','%e3%83%87%e3%82%b6%e3%82%a4%e3%83%8a%e3%83%bc%e5%90%91%e3%81%91web%e3%81%a8%e3%82%b9%e3%83%9e%e3%83%9b%e3%82%a2%e3%83%97%e3%83%aa%e3%81%ae%e8%a9%b1','','','2017-12-08 10:26:20','2017-12-08 01:26:20','',0,'http://www.tmotoki.net/?p=246',0,'post','',0),(247,1,'2017-12-08 10:26:20','2017-12-08 01:26:20','デザイナー向けのセミナーで、\r\n正直あまり期待してなかったのですが、\r\nすごく良い内容のセミナーでした。\r\n\r\nWebフロントエンドの技術とサーバサイドの技術が、\r\nスマホアプリと融合して、\r\n今後もっと簡単にマルチプラットフォームが実現できていけそうでした。\r\n\r\n自分の目指す方向性が間違ってなさそうな気がして、\r\nこのまま進んでいきたいと思いまいした。\r\n\r\nというわけで、来週くらいまでに、\r\nAndroidアプリでこのサイトを表示するやつを作ってみたいと思います。\r\n（できたら）\r\nほんとはiOSアプリを作りたいのですが、\r\nMac持ってないので。。ああそろそろほしくなってきた。。','デザイナー向けWebとスマホアプリの話','','inherit','closed','closed','','246-revision-v1','','','2017-12-08 10:26:20','2017-12-08 01:26:20','',246,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/246-revision-v1/',0,'revision','',0),(248,1,'2017-12-13 00:29:30','2017-12-12 15:29:30','<span style=\"color: #747474; font-family: \'Open Sans\', sans-serif; font-size: 14px;\">#06 擬似クラスを使ってみよう</span>\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31706\">https://dotinstall.com/lessons/basic_css_v3/31706</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/06/\">http://www.tmotoki.net/static/dot_install/02_css/06/</a>\r\n\r\n■メモ\r\n疑似クラスとは、htmlで指定しなくてもあらかじめ決まっているもの。\r\nたとえば、あるタグの1つ目の子供に対してスタイルをつけたい場合は、\r\nfirst-childをつけるなど。\r\n\r\n:（コロン）でタグの後ろに指定する。\r\n指定する順番にも注意すること。\r\njavascriptとかを使わなくてもここまでできるんだね。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n セレクタ\r\n 疑似クラス\r\n*/\r\n\r\n/* ulタグの子liの1つ目 */\r\n/* css3では2つ目、最後といった指定もできる */\r\nul li:first-child { color:skyblue; }\r\n\r\n\r\n/* \r\n aタグにはこの順番で指定しないと、\r\n 正しく反映されない可能性もある。\r\n*/\r\n\r\na:link { color: violet; }		/* 未訪問 */\r\na:visited { color: orange; }	/* 訪問済 */\r\na:hover { color: pink; }		/* マウスを上に乗せる */\r\na:active { color: red; }		/* クリック */\r\n\r\n/* カーソルがinputタグにある場合 */\r\ninput:focus { background: skyblue;}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;ul&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n		&lt;/ul&gt;\r\n		&lt;p&gt;\r\n			&lt;a href=\"http://dotinstall.com\"&gt;\r\n				Dotinstall\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;a href=\"http://yahoo.com\"&gt;\r\n				Yahoo\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		\r\n		&lt;p&gt;\r\n			&lt;input type=\"text\"&gt;\r\n		&lt;/p&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #06(ドットインストール)','','publish','open','open','','css-06%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:46:22','2017-12-27 18:46:22','',0,'http://www.tmotoki.net/?p=248',0,'post','',0),(249,1,'2017-12-11 23:50:03','2017-12-11 14:50:03','今週中にアプリ作成は無理かな。。\r\n無理せずボチボチやります。\r\n今週はCSS終わらせる・・！\r\n\r\nそのうちグラフデータベースとか、\r\nあまり世に知られてなくて、\r\n少し自分が詳しいものを載せていきたいと思ってます。\r\n\r\nぶっちゃけ使い方知ってるだけで、\r\nそんなに使いこなせてないなんだけど、\r\n使いこなせたら便利だろうなあ。\r\n\r\n個人的にはNoSQLとRDBは使いどころを分ければ良い感じかなと思ってます。','ああ。。','','publish','open','open','','%e3%81%82%e3%81%82%e3%80%82%e3%80%82','','','2017-12-11 23:52:31','2017-12-11 14:52:31','',0,'http://www.tmotoki.net/?p=249',0,'post','',0),(250,1,'2017-12-11 23:50:03','2017-12-11 14:50:03','今週中にアプリ作成は無理かな。。\r\n無理せずボチボチやります。\r\n今週はCSS終わらせる・・！','ああ。。','','inherit','closed','closed','','249-revision-v1','','','2017-12-11 23:50:03','2017-12-11 14:50:03','',249,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/249-revision-v1/',0,'revision','',0),(251,1,'2017-12-11 23:52:05','2017-12-11 14:52:05','今週中にアプリ作成は無理かな。。\n無理せずボチボチやります。\n今週はCSS終わらせる・・！\n\nそのうちグラフデータベースとか、\nあまり世に知られてなくて、\n少し自分が詳しいものを載せていきたいと思ってます。\n\nぶっちゃけ使い方知ってるだけで、\nそんなに使いこなせてないなんだけど、\n使いこなせたら便利だろうなあ。\n\n個人的にはNoSQLとRDBは使いどころを分ければよ','ああ。。','','inherit','closed','closed','','249-autosave-v1','','','2017-12-11 23:52:05','2017-12-11 14:52:05','',249,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/249-autosave-v1/',0,'revision','',0),(252,1,'2017-12-11 23:52:31','2017-12-11 14:52:31','今週中にアプリ作成は無理かな。。\r\n無理せずボチボチやります。\r\n今週はCSS終わらせる・・！\r\n\r\nそのうちグラフデータベースとか、\r\nあまり世に知られてなくて、\r\n少し自分が詳しいものを載せていきたいと思ってます。\r\n\r\nぶっちゃけ使い方知ってるだけで、\r\nそんなに使いこなせてないなんだけど、\r\n使いこなせたら便利だろうなあ。\r\n\r\n個人的にはNoSQLとRDBは使いどころを分ければ良い感じかなと思ってます。','ああ。。','','inherit','closed','closed','','249-revision-v1','','','2017-12-11 23:52:31','2017-12-11 14:52:31','',249,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/249-revision-v1/',0,'revision','',0),(253,1,'2017-12-13 00:29:30','2017-12-12 15:29:30','<ul class=\"light-color-breadcrumb\">\r\n<ul class=\"light-color-breadcrumb\"></ul>\r\n</ul>\r\n<span style=\"color: #747474; font-family: \'Open Sans\', sans-serif; font-size: 14px;\">#06 擬似クラスを使ってみよう</span>\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31706\">https://dotinstall.com/lessons/basic_css_v3/31706</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/06/\">http://www.tmotoki.net/static/dot_install/02_css/06/</a>\r\n\r\n■メモ\r\n疑似クラスとは、htmlで指定しなくてもあらかじめ決まっているもの。\r\nたとえば、あるタグの1つ目の子供に対してスタイルをつけたい場合は、\r\nfirst-childをつけるなど。\r\n\r\n:（コロン）でタグの後ろに指定する。\r\n指定する順番にも注意すること。\r\njavascriptとかを使わなくてもここまでできるんだね。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n セレクタ\r\n 疑似クラス\r\n*/\r\n\r\n/* ulタグの子liの1つ目 */\r\n/* css3では2つ目、最後といった指定もできる */\r\nul li:first-child { color:skyblue; }\r\n\r\n\r\n/* \r\n aタグにはこの順番で指定しないと、\r\n 正しく反映されない可能性もある。\r\n*/\r\n\r\na:link { color: violet; }		/* 未訪問 */\r\na:visited { color: orange; }	/* 訪問済 */\r\na:hover { color: pink; }		/* マウスを上に乗せる */\r\na:active { color: red; }		/* クリック */\r\n\r\n/* カーソルがinputタグにある場合 */\r\ninput:focus { background: skyblue;}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;ul&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n		&lt;/ul&gt;\r\n		&lt;p&gt;\r\n			&lt;a href=\"http://dotinstall.com\"&gt;\r\n				Dotinstall\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;a href=\"http://yahoo.com\"&gt;\r\n				Yahoo\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		\r\n		&lt;p&gt;\r\n			&lt;input type=\"text\"&gt;\r\n		&lt;/p&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #06(ドットインストール)','','inherit','closed','closed','','248-revision-v1','','','2017-12-13 00:29:30','2017-12-12 15:29:30','',248,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/248-revision-v1/',0,'revision','',0),(254,1,'2017-12-13 00:50:05','2017-12-12 15:50:05','デフォルト設定だとCSS等の色がなく、\r\nなんだかやりにくいので、設定したときのメモ。\r\n\r\n■参考\r\n\r\n<a href=\"https://blog.codecamp.jp/utility_of_sakuraeditor\">https://blog.codecamp.jp/utility_of_sakuraeditor</a>\r\n\r\n・タブ表示にする\r\n・htmlの言語設定をUTF-8にする\r\n・共通設定の強調キーワードとタイプ定義\r\n\r\nPHP\r\njavascript\r\n\r\n設定ファイルの場所\r\n\r\n---\r\n32bit版だとだいたいこのあたり\r\nC:\\Program Files (x86)\\sakura\\keyword\r\n\r\nCSSはデフォルトでは存在しない。\r\n以下のサイトからCSS3を取得する。\r\n\r\n<a href=\"http://d.hatena.ne.jp/momdo/20111124/p1\">http://d.hatena.ne.jp/momdo/20111124/p1</a>\r\n\r\n取得したzipを解凍して適当なフォルダへ置く。\r\nsakuraの下にaddとかフォルダを作っておけばいいのでは？\r\n\r\nタイプ別一覧でインポートから、\r\nCSS.iniをインポートする。そのままでOK。\r\n\r\nこれで幾分みやすくなった。\r\n\r\nただ、CSSの設定ファイルは今後更新されないそうなので、\r\n本気で開発する場合は別のエディタを使ったほうがよいかも。\r\n\r\n自分としては統合開発環境だとNetBeansを使っているが、\r\nまたそれは別の機会に。','Web開発向けsakuraエディタの設定','','publish','open','open','','web%e9%96%8b%e7%99%ba%e5%90%91%e3%81%91sakura%e3%82%a8%e3%83%87%e3%82%a3%e3%82%bf%e3%81%ae%e8%a8%ad%e5%ae%9a','','','2017-12-13 00:52:57','2017-12-12 15:52:57','',0,'http://www.tmotoki.net/?p=254',0,'post','',0),(255,1,'2017-12-13 00:50:05','2017-12-12 15:50:05','デフォルト設定だとCSS等の色がなく、\r\nなんだかやりにくいので、設定したときのメモ。\r\n\r\n■参考\r\n\r\n<a href=\"https://blog.codecamp.jp/utility_of_sakuraeditor\">https://blog.codecamp.jp/utility_of_sakuraeditor</a>\r\n\r\n・タブ表示にする\r\n・htmlの言語設定をUTF-8にする\r\n・共通設定の強調キーワードとタイプ定義\r\n\r\nPHP\r\njavascript\r\n\r\n設定ファイルの場所\r\n\r\n---\r\n32bit版だとだいたいこのあたり\r\nC:\\Program Files (x86)\\sakura\\keyword\r\n\r\nCSSはデフォルトでは存在しない。\r\n以下のサイトからCSS3を取得する。\r\n\r\n<a href=\"http://d.hatena.ne.jp/momdo/20111124/p1\">http://d.hatena.ne.jp/momdo/20111124/p1</a>\r\n\r\n取得したzipを解凍して適当なフォルダへ置く。\r\nsakuraの下にaddとかフォルダを作っておけばいいのでは？\r\n\r\nタイプ別一覧でインポートから、\r\nCSS.iniをインポートする。そのままでOK。\r\n\r\nこれで幾分みやすくなった。','Web開発向けsakuraエディタの設定','','inherit','closed','closed','','254-revision-v1','','','2017-12-13 00:50:05','2017-12-12 15:50:05','',254,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/254-revision-v1/',0,'revision','',0),(256,1,'2017-12-13 00:52:07','2017-12-12 15:52:07','デフォルト設定だとCSS等の色がなく、\nなんだかやりにくいので、設定したときのメモ。\n\n■参考\n\n<a href=\"https://blog.codecamp.jp/utility_of_sakuraeditor\">https://blog.codecamp.jp/utility_of_sakuraeditor</a>\n\n・タブ表示にする\n・htmlの言語設定をUTF-8にする\n・共通設定の強調キーワードとタイプ定義\n\nPHP\njavascript\n\n設定ファイルの場所\n\n---\n32bit版だとだいたいこのあたり\nC:\\Program Files (x86)\\sakura\\keyword\n\nCSSはデフォルトでは存在しない。\n以下のサイトからCSS3を取得する。\n\n<a href=\"http://d.hatena.ne.jp/momdo/20111124/p1\">http://d.hatena.ne.jp/momdo/20111124/p1</a>\n\n取得したzipを解凍して適当なフォルダへ置く。\nsakuraの下にaddとかフォルダを作っておけばいいのでは？\n\nタイプ別一覧でインポートから、\nCSS.iniをインポートする。そのままでOK。\n\nこれで幾分みやすくなった。\n\nただ、CSSの設定ファイルは今後更新されないそうなので、\n本気で開発する場合は別のエディタを使ったほうがよいかも。\n\n自分としてはとうごうかいｈ','Web開発向けsakuraエディタの設定','','inherit','closed','closed','','254-autosave-v1','','','2017-12-13 00:52:07','2017-12-12 15:52:07','',254,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/254-autosave-v1/',0,'revision','',0),(257,1,'2017-12-13 00:52:57','2017-12-12 15:52:57','デフォルト設定だとCSS等の色がなく、\r\nなんだかやりにくいので、設定したときのメモ。\r\n\r\n■参考\r\n\r\n<a href=\"https://blog.codecamp.jp/utility_of_sakuraeditor\">https://blog.codecamp.jp/utility_of_sakuraeditor</a>\r\n\r\n・タブ表示にする\r\n・htmlの言語設定をUTF-8にする\r\n・共通設定の強調キーワードとタイプ定義\r\n\r\nPHP\r\njavascript\r\n\r\n設定ファイルの場所\r\n\r\n---\r\n32bit版だとだいたいこのあたり\r\nC:\\Program Files (x86)\\sakura\\keyword\r\n\r\nCSSはデフォルトでは存在しない。\r\n以下のサイトからCSS3を取得する。\r\n\r\n<a href=\"http://d.hatena.ne.jp/momdo/20111124/p1\">http://d.hatena.ne.jp/momdo/20111124/p1</a>\r\n\r\n取得したzipを解凍して適当なフォルダへ置く。\r\nsakuraの下にaddとかフォルダを作っておけばいいのでは？\r\n\r\nタイプ別一覧でインポートから、\r\nCSS.iniをインポートする。そのままでOK。\r\n\r\nこれで幾分みやすくなった。\r\n\r\nただ、CSSの設定ファイルは今後更新されないそうなので、\r\n本気で開発する場合は別のエディタを使ったほうがよいかも。\r\n\r\n自分としては統合開発環境だとNetBeansを使っているが、\r\nまたそれは別の機会に。','Web開発向けsakuraエディタの設定','','inherit','closed','closed','','254-revision-v1','','','2017-12-13 00:52:57','2017-12-12 15:52:57','',254,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/254-revision-v1/',0,'revision','',0),(258,1,'2017-12-13 21:21:55','2017-12-13 12:21:55','SQLサーバーやオラクルDBが、\r\nグラフデータベースに注目し始めたということで、\r\nまがりなりにも業務で使っている自分の目線で、\r\nグラフデータベースの利点をまとめてみました。\r\n\r\nちなみに、完全に自分向けのメモです。\r\n\r\n＜利点＞\r\n・関係自体に意味を持たせられる\r\n・関係にも属性値を持たせることができる\r\n・関係に方向がある\r\n・同じカテゴリでも構造が不一致で構わない\r\n・直感的で連想的である\r\n\r\n&nbsp;\r\n\r\n特に関係自体に意味をもたせることが強みと思われる。\r\n\r\n&nbsp;\r\n\r\n従来のRDBは、\r\nスキーマに基づいてほしい答えがとれるようにしていきますが、\r\nグラフデータベースだと、\r\n\r\n「山田さんの親友は何人いますか？」\r\n↓\r\n「そのうち女性は何人ですか？」\r\n↓\r\n「その女性は既婚者ですか？」\r\n\r\nみたいな感じで、\r\n感覚で情報をとっているかと思います。\r\n\r\n&nbsp;\r\n\r\n規律のあるデータを管理する上ではRDB、\r\nいろいろなデータが混在するケースではグラフDBといった、\r\nケースに合った利用を考えるべきだと思う。\r\n\r\n&nbsp;\r\n\r\nまたそのうちまとめていきます。','グラフデータベースの利点','','publish','open','open','','%e3%82%b0%e3%83%a9%e3%83%95%e3%83%87%e3%83%bc%e3%82%bf%e3%83%99%e3%83%bc%e3%82%b9%e3%81%ae%e5%88%a9%e7%82%b9','','','2017-12-14 00:00:11','2017-12-13 15:00:11','',0,'http://www.tmotoki.net/?p=258',0,'post','',0),(259,1,'2017-12-13 12:19:06','2017-12-13 03:19:06','・関係自体に意味を持たせられる\r\n\r\n・関係にも属性値を持たせることができる\r\n\r\n・関係に方向がある\r\n\r\n・同じカテゴリでも構造が不一致で構わない\r\n\r\n・直感的で連想的である','グラフデータベースの利点','','inherit','closed','closed','','258-revision-v1','','','2017-12-13 12:19:06','2017-12-13 03:19:06','',258,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/258-revision-v1/',0,'revision','',0),(261,1,'2017-12-13 23:58:25','2017-12-13 14:58:25','SQLサーバーやオラクルDBが、\nグラフデータベースに注目し始めたということで、\nまがりなりにも業務で使っている自分の目線で、\nグラフデータベースの利点をまとめてみました。\n\nちなみに、完全に自分向けのメモです。\n\n＜利点＞\n・関係自体に意味を持たせられる\n・関係にも属性値を持たせることができる\n・関係に方向がある\n・同じカテゴリでも構造が不一致で構わない\n・直感的で連想的である\n\n&nbsp;\n\n特に関係自体に意味をもたせることが強みと思われる。\n\n&nbsp;\n\n従来のRDBは、\nスキーマに基づいてほしい答えがとれるようにしていきますが、\nグラフデータベースだと、\n\n「山田さんの親友は何人いますか？」\n↓\n「そのうち女性は何人ですか？」\n↓\n「その女性は既婚者ですか？」\n\nみたいな感じで、\n感覚で情報をとっているかと思います。\n\n&nbsp;\n\n１つ言えるのは、\n規律のあｒ\n\n&nbsp;\n\nまたそのうちまとめていきますよ。','グラフデータベースの利点','','inherit','closed','closed','','258-autosave-v1','','','2017-12-13 23:58:25','2017-12-13 14:58:25','',258,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/258-autosave-v1/',0,'revision','',0),(262,1,'2017-12-13 23:50:24','2017-12-13 14:50:24','SQLサーバーやオラクルDBが、\r\nグラフデータベースに注目し始めたということで、\r\nまがりなりにも業務で使っている自分の目線で、\r\nグラフデータベースの利点をまとめてみました。\r\n\r\nちなみに、完全に自分向けのメモです。\r\n\r\n＜利点＞\r\n・関係自体に意味を持たせられる\r\n・関係にも属性値を持たせることができる\r\n・関係に方向がある\r\n・同じカテゴリでも構造が不一致で構わない\r\n・直感的で連想的である\r\n\r\n特に関係自体に意味をもたせることが強みと思われる。\r\n\r\n従来のRDBは、\r\nスキーマに基づいてほしい答えがとれるようにしていきますが、\r\nグラフデータベースだと、\r\n\r\n「山田さんの親友は何人いますか？」\r\n↓\r\n「そのうち女性は何人ですか？」\r\n↓\r\n「その女性は既婚者ですか？」\r\n\r\nみたいな感じで、\r\n感覚で情報をとっているかと思います。\r\n\r\nまたそのうちまとめていきますよ。','グラフデータベースの利点','','inherit','closed','closed','','258-revision-v1','','','2017-12-13 23:50:24','2017-12-13 14:50:24','',258,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/258-revision-v1/',0,'revision','',0),(263,1,'2017-12-14 00:00:11','2017-12-13 15:00:11','SQLサーバーやオラクルDBが、\r\nグラフデータベースに注目し始めたということで、\r\nまがりなりにも業務で使っている自分の目線で、\r\nグラフデータベースの利点をまとめてみました。\r\n\r\nちなみに、完全に自分向けのメモです。\r\n\r\n＜利点＞\r\n・関係自体に意味を持たせられる\r\n・関係にも属性値を持たせることができる\r\n・関係に方向がある\r\n・同じカテゴリでも構造が不一致で構わない\r\n・直感的で連想的である\r\n\r\n&nbsp;\r\n\r\n特に関係自体に意味をもたせることが強みと思われる。\r\n\r\n&nbsp;\r\n\r\n従来のRDBは、\r\nスキーマに基づいてほしい答えがとれるようにしていきますが、\r\nグラフデータベースだと、\r\n\r\n「山田さんの親友は何人いますか？」\r\n↓\r\n「そのうち女性は何人ですか？」\r\n↓\r\n「その女性は既婚者ですか？」\r\n\r\nみたいな感じで、\r\n感覚で情報をとっているかと思います。\r\n\r\n&nbsp;\r\n\r\n規律のあるデータを管理する上ではRDB、\r\nいろいろなデータが混在するケースではグラフDBといった、\r\nケースに合った利用を考えるべきだと思う。\r\n\r\n&nbsp;\r\n\r\nまたそのうちまとめていきます。','グラフデータベースの利点','','inherit','closed','closed','','258-revision-v1','','','2017-12-14 00:00:11','2017-12-13 15:00:11','',258,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/258-revision-v1/',0,'revision','',0),(264,1,'2017-12-14 21:45:42','2017-12-14 12:45:42','AWSのEC2でこのブログを運営していますが、\r\nなんだか頻繁固まって、\r\n手動で再起動することが多いので、\r\nとりあえず定期的に再起動するようにしたいと思い調べました。\r\n\r\n&nbsp;\r\n\r\nいくつかサイトがあったが、ここが一番分かりやすかった。\r\n<a href=\"http://x68000.q-e-d.net/~68user/unix/pickup?crontab\">http://x68000.q-e-d.net/~68user/unix/pickup?crontab</a>\r\n\r\n＜引用＞\r\nUNIX・Linux では cron または crond というデーモンが常時起動しており、\r\n指定の時刻になると指定のコマンドを実行してくれる。\r\ncrontab コマンドを使うと、その設定ファイルを表示・設定・更新・削除することができる。\r\n\r\ncrontab -e\r\nで環境変数EDITORに登録されている\r\nテキストエディタで開けるらしいです。\r\n\r\nが、\r\n\r\nだいたいのサイトでは非推奨とされていました。\r\n\r\n理由は簡単。\r\ncrontab -r とうっかり打とうものなら、\r\n全部消えてしまうらしい。恐ろしい。\r\n\r\n&nbsp;\r\n\r\n■cronが動いているかどうか\r\n<pre class=\"lang:sh decode:true \" title=\"確認\">service crond status\r\n\r\n#もしくは\r\n\r\n/etc/rc.d/init.d/crond status\r\n\r\n#動いていたら\r\n#crond (pid  2845) is running...\r\n#のように表示される</pre>\r\n&nbsp;\r\n\r\n&nbsp;\r\n\r\n■記述ルール\r\n<pre class=\"lang:sh decode:true\" title=\"ルール\">* * * * * command</pre>\r\n分　時　日　月　曜日　コマンド\r\n\r\n間にスペースがいる。\r\n\r\n&nbsp;\r\n\r\n■作業\r\n<pre class=\"lang:sh decode:true\" title=\"編集と実装\">#テキストエディタで任意のファイルを編集\r\n#ホームに.crontabを作成した\r\n\r\nvi ~/.crontab\r\n\r\n\r\n#以下をファイルの中に記述する\r\n#朝5:30に再起動を実施する\r\n\r\n30 5 * * * reboot\r\n\r\n\r\n#以下のコマンドでcronに反映する\r\n#欠点はこのファイルとcronが一致している保証はない\r\n\r\ncrontab ~/.crontab</pre>\r\nちなみにcrontabコマンドは管理者権限が実行に必要なので、\r\n必要に応じてコマンドの頭にsudoをつけてください。\r\n\r\n■設定の確認\r\n<pre class=\"lang:sh decode:true \" title=\"結果\">crontab -l\r\n\r\n#と実行すると\r\n\r\n30 5 * * * reboot\r\n\r\n#このように設定一覧がでてくる。\r\n#ていうか-rしそうになって怖い。\r\n#他に方法はないのかな。\r\n\r\n#ちなみにこれも管理者権限で実行が必要です。</pre>\r\n&nbsp;\r\n\r\n果たしてうまくいくのかな？','Linux(UNIX)で定期的に再起動をする','','publish','open','open','','linuxunix%e3%81%a7%e5%ae%9a%e6%9c%9f%e7%9a%84%e3%81%ab%e5%86%8d%e8%b5%b7%e5%8b%95%e3%82%92%e3%81%99%e3%82%8b','','','2017-12-14 21:55:00','2017-12-14 12:55:00','',0,'http://www.tmotoki.net/?p=264',0,'post','',0),(265,1,'2017-12-14 21:45:42','2017-12-14 12:45:42','AWSのEC2でこのブログを運営していますが、\r\nなんだか頻繁固まって、\r\n手動で再起動することが多いので、\r\nとりあえず定期的に再起動するようにしたいと思い調べました。\r\n\r\n&nbsp;\r\n\r\nいくつかサイトがあったが、ここが一番分かりやすかった。\r\n<a href=\"http://x68000.q-e-d.net/~68user/unix/pickup?crontab\">http://x68000.q-e-d.net/~68user/unix/pickup?crontab</a>\r\n\r\n＜引用＞\r\nUNIX・Linux では cron または crond というデーモンが常時起動しており、\r\n指定の時刻になると指定のコマンドを実行してくれる。\r\ncrontab コマンドを使うと、その設定ファイルを表示・設定・更新・削除することができる。\r\n\r\ncrontab -e\r\nで環境変数EDITORに登録されている\r\nテキストエディタで開けるらしいです。\r\n\r\nが、\r\n\r\nだいたいのサイトでは非推奨とされていました。\r\n\r\n理由は簡単。\r\ncrontab -r とうっかり打とうものなら、\r\n全部消えてしまうらしい。恐ろしい。\r\n\r\n■記述ルール\r\n<pre class=\"lang:sh decode:true\" title=\"ルール\">* * * * * command</pre>\r\n分　時　日　月　曜日　コマンド\r\n\r\n間にスペースがいる。\r\n\r\n作業\r\n<pre class=\"lang:sh decode:true\" title=\"編集と実装\">#テキストエディタで任意のファイルを編集\r\n#ホームに.crontabを作成した\r\n\r\nvi ~/.crontab\r\n\r\n\r\n#以下をファイルの中に記述する\r\n#朝5:30に再起動を実施する\r\n\r\n30 5 * * * reboot\r\n\r\n\r\n#以下のコマンドでcronに反映する\r\n#欠点はこのファイルとcronが一致している保証はない\r\n\r\ncrontab ~/.crontab</pre>\r\n果たしてうまくいくのかな？','Linux(UNIX)で定期的に再起動をする','','inherit','closed','closed','','264-revision-v1','','','2017-12-14 21:45:42','2017-12-14 12:45:42','',264,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/264-revision-v1/',0,'revision','',0),(266,1,'2017-12-14 21:46:31','2017-12-14 12:46:31','AWSのEC2でこのブログを運営していますが、\r\nなんだか頻繁固まって、\r\n手動で再起動することが多いので、\r\nとりあえず定期的に再起動するようにしたいと思い調べました。\r\n\r\n&nbsp;\r\n\r\nいくつかサイトがあったが、ここが一番分かりやすかった。\r\n<a href=\"http://x68000.q-e-d.net/~68user/unix/pickup?crontab\">http://x68000.q-e-d.net/~68user/unix/pickup?crontab</a>\r\n\r\n＜引用＞\r\nUNIX・Linux では cron または crond というデーモンが常時起動しており、\r\n指定の時刻になると指定のコマンドを実行してくれる。\r\ncrontab コマンドを使うと、その設定ファイルを表示・設定・更新・削除することができる。\r\n\r\ncrontab -e\r\nで環境変数EDITORに登録されている\r\nテキストエディタで開けるらしいです。\r\n\r\nが、\r\n\r\nだいたいのサイトでは非推奨とされていました。\r\n\r\n理由は簡単。\r\ncrontab -r とうっかり打とうものなら、\r\n全部消えてしまうらしい。恐ろしい。\r\n\r\n■記述ルール\r\n<pre class=\"lang:sh decode:true\" title=\"ルール\">* * * * * command</pre>\r\n分　時　日　月　曜日　コマンド\r\n\r\n間にスペースがいる。\r\n\r\n&nbsp;\r\n\r\n■作業\r\n<pre class=\"lang:sh decode:true\" title=\"編集と実装\">#テキストエディタで任意のファイルを編集\r\n#ホームに.crontabを作成した\r\n\r\nvi ~/.crontab\r\n\r\n\r\n#以下をファイルの中に記述する\r\n#朝5:30に再起動を実施する\r\n\r\n30 5 * * * reboot\r\n\r\n\r\n#以下のコマンドでcronに反映する\r\n#欠点はこのファイルとcronが一致している保証はない\r\n\r\ncrontab ~/.crontab</pre>\r\n果たしてうまくいくのかな？','Linux(UNIX)で定期的に再起動をする','','inherit','closed','closed','','264-revision-v1','','','2017-12-14 21:46:31','2017-12-14 12:46:31','',264,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/264-revision-v1/',0,'revision','',0),(267,1,'2017-12-14 21:46:47','2017-12-14 12:46:47','AWSのEC2でこのブログを運営していますが、\r\nなんだか頻繁固まって、\r\n手動で再起動することが多いので、\r\nとりあえず定期的に再起動するようにしたいと思い調べました。\r\n\r\n&nbsp;\r\n\r\nいくつかサイトがあったが、ここが一番分かりやすかった。\r\n<a href=\"http://x68000.q-e-d.net/~68user/unix/pickup?crontab\">http://x68000.q-e-d.net/~68user/unix/pickup?crontab</a>\r\n\r\n＜引用＞\r\nUNIX・Linux では cron または crond というデーモンが常時起動しており、\r\n指定の時刻になると指定のコマンドを実行してくれる。\r\ncrontab コマンドを使うと、その設定ファイルを表示・設定・更新・削除することができる。\r\n\r\ncrontab -e\r\nで環境変数EDITORに登録されている\r\nテキストエディタで開けるらしいです。\r\n\r\nが、\r\n\r\nだいたいのサイトでは非推奨とされていました。\r\n\r\n理由は簡単。\r\ncrontab -r とうっかり打とうものなら、\r\n全部消えてしまうらしい。恐ろしい。\r\n\r\n&nbsp;\r\n\r\n■記述ルール\r\n<pre class=\"lang:sh decode:true\" title=\"ルール\">* * * * * command</pre>\r\n分　時　日　月　曜日　コマンド\r\n\r\n間にスペースがいる。\r\n\r\n&nbsp;\r\n\r\n■作業\r\n<pre class=\"lang:sh decode:true\" title=\"編集と実装\">#テキストエディタで任意のファイルを編集\r\n#ホームに.crontabを作成した\r\n\r\nvi ~/.crontab\r\n\r\n\r\n#以下をファイルの中に記述する\r\n#朝5:30に再起動を実施する\r\n\r\n30 5 * * * reboot\r\n\r\n\r\n#以下のコマンドでcronに反映する\r\n#欠点はこのファイルとcronが一致している保証はない\r\n\r\ncrontab ~/.crontab</pre>\r\n果たしてうまくいくのかな？','Linux(UNIX)で定期的に再起動をする','','inherit','closed','closed','','264-revision-v1','','','2017-12-14 21:46:47','2017-12-14 12:46:47','',264,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/264-revision-v1/',0,'revision','',0),(268,1,'2017-12-14 21:54:50','2017-12-14 12:54:50','AWSのEC2でこのブログを運営していますが、\nなんだか頻繁固まって、\n手動で再起動することが多いので、\nとりあえず定期的に再起動するようにしたいと思い調べました。\n\n&nbsp;\n\nいくつかサイトがあったが、ここが一番分かりやすかった。\n<a href=\"http://x68000.q-e-d.net/~68user/unix/pickup?crontab\">http://x68000.q-e-d.net/~68user/unix/pickup?crontab</a>\n\n＜引用＞\nUNIX・Linux では cron または crond というデーモンが常時起動しており、\n指定の時刻になると指定のコマンドを実行してくれる。\ncrontab コマンドを使うと、その設定ファイルを表示・設定・更新・削除することができる。\n\ncrontab -e\nで環境変数EDITORに登録されている\nテキストエディタで開けるらしいです。\n\nが、\n\nだいたいのサイトでは非推奨とされていました。\n\n理由は簡単。\ncrontab -r とうっかり打とうものなら、\n全部消えてしまうらしい。恐ろしい。\n\n&nbsp;\n\n■cronが動いているかどうか\n<pre class=\"lang:sh decode:true \" title=\"確認\">service crond status\n\n#もしくは\n\n/etc/rc.d/init.d/crond status\n\n#動いていたら\n#crond (pid  2845) is running...\n#のように表示される</pre>\n&nbsp;\n\n&nbsp;\n\n■記述ルール\n<pre class=\"lang:sh decode:true\" title=\"ルール\">* * * * * command</pre>\n分　時　日　月　曜日　コマンド\n\n間にスペースがいる。\n\n&nbsp;\n\n■作業\n<pre class=\"lang:sh decode:true\" title=\"編集と実装\">#テキストエディタで任意のファイルを編集\n#ホームに.crontabを作成した\n\nvi ~/.crontab\n\n\n#以下をファイルの中に記述する\n#朝5:30に再起動を実施する\n\n30 5 * * * reboot\n\n\n#以下のコマンドでcronに反映する\n#欠点はこのファイルとcronが一致している保証はない\n\ncrontab ~/.crontab</pre>\nちなみにcrontabコマンドは管理者権限が実行に必要なので、\n必要に応じてコマンドの頭にsudoをつけてください。\n\n■設定の確認\n\n&nbsp;\n\n果たしてうまくいくのかな？','Linux(UNIX)で定期的に再起動をする','','inherit','closed','closed','','264-autosave-v1','','','2017-12-14 21:54:50','2017-12-14 12:54:50','',264,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/264-autosave-v1/',0,'revision','',0),(269,1,'2017-12-14 21:55:00','2017-12-14 12:55:00','AWSのEC2でこのブログを運営していますが、\r\nなんだか頻繁固まって、\r\n手動で再起動することが多いので、\r\nとりあえず定期的に再起動するようにしたいと思い調べました。\r\n\r\n&nbsp;\r\n\r\nいくつかサイトがあったが、ここが一番分かりやすかった。\r\n<a href=\"http://x68000.q-e-d.net/~68user/unix/pickup?crontab\">http://x68000.q-e-d.net/~68user/unix/pickup?crontab</a>\r\n\r\n＜引用＞\r\nUNIX・Linux では cron または crond というデーモンが常時起動しており、\r\n指定の時刻になると指定のコマンドを実行してくれる。\r\ncrontab コマンドを使うと、その設定ファイルを表示・設定・更新・削除することができる。\r\n\r\ncrontab -e\r\nで環境変数EDITORに登録されている\r\nテキストエディタで開けるらしいです。\r\n\r\nが、\r\n\r\nだいたいのサイトでは非推奨とされていました。\r\n\r\n理由は簡単。\r\ncrontab -r とうっかり打とうものなら、\r\n全部消えてしまうらしい。恐ろしい。\r\n\r\n&nbsp;\r\n\r\n■cronが動いているかどうか\r\n<pre class=\"lang:sh decode:true \" title=\"確認\">service crond status\r\n\r\n#もしくは\r\n\r\n/etc/rc.d/init.d/crond status\r\n\r\n#動いていたら\r\n#crond (pid  2845) is running...\r\n#のように表示される</pre>\r\n&nbsp;\r\n\r\n&nbsp;\r\n\r\n■記述ルール\r\n<pre class=\"lang:sh decode:true\" title=\"ルール\">* * * * * command</pre>\r\n分　時　日　月　曜日　コマンド\r\n\r\n間にスペースがいる。\r\n\r\n&nbsp;\r\n\r\n■作業\r\n<pre class=\"lang:sh decode:true\" title=\"編集と実装\">#テキストエディタで任意のファイルを編集\r\n#ホームに.crontabを作成した\r\n\r\nvi ~/.crontab\r\n\r\n\r\n#以下をファイルの中に記述する\r\n#朝5:30に再起動を実施する\r\n\r\n30 5 * * * reboot\r\n\r\n\r\n#以下のコマンドでcronに反映する\r\n#欠点はこのファイルとcronが一致している保証はない\r\n\r\ncrontab ~/.crontab</pre>\r\nちなみにcrontabコマンドは管理者権限が実行に必要なので、\r\n必要に応じてコマンドの頭にsudoをつけてください。\r\n\r\n■設定の確認\r\n<pre class=\"lang:sh decode:true \" title=\"結果\">crontab -l\r\n\r\n#と実行すると\r\n\r\n30 5 * * * reboot\r\n\r\n#このように設定一覧がでてくる。\r\n#ていうか-rしそうになって怖い。\r\n#他に方法はないのかな。\r\n\r\n#ちなみにこれも管理者権限で実行が必要です。</pre>\r\n&nbsp;\r\n\r\n果たしてうまくいくのかな？','Linux(UNIX)で定期的に再起動をする','','inherit','closed','closed','','264-revision-v1','','','2017-12-14 21:55:00','2017-12-14 12:55:00','',264,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/264-revision-v1/',0,'revision','',0),(270,1,'2017-12-14 22:08:17','2017-12-14 13:08:17','','wordpressIcon','','inherit','open','closed','','wordpressicon','','','2017-12-14 22:08:17','2017-12-14 13:08:17','',0,'http://www.tmotoki.net/wp-content/uploads/2017/12/wordpressIcon.jpg',0,'attachment','image/jpeg',0),(273,1,'2017-12-14 23:26:00','2017-12-14 14:26:00','使っているテーマが何故か公開日も表示しないので、\r\n自分で直接いじって表示しました。\r\n\r\nなんだかいろいろ記事がありましたが、\r\nどのファイルを編集するか、\r\n知ってる前提で書かれてる記事が多かったので、\r\n分からなかった点を記載してきます。\r\n\r\n■テーマ\r\n/(Wordpressの置き場所)/wp-content/themes/\r\n\r\nここにWordPressのテーマが入っています。\r\n目的のテーマがディレクトリになっているので、その中に入ります。\r\n\r\nトップページ→index.php\r\n投稿ページ→single.php\r\nサイドナビ→sidebar.php\r\nテーマ専用の機能→functions.php\r\n\r\n※WordPress全体用のfunctions.phpもあるので間違えないように注意が必要\r\n\r\n今回は投稿ページを直したいので、\r\nsingle.phpをテキストエディタで開きます。\r\n\r\nget_template_part(\'templates/content\' \'page\')\r\nというものが、ページがあるだけ読み込むという処理がありました。\r\nこれはなんですか？\r\n\r\nget_template_part()とは？\r\n好きなテンプレートを読み込む関数です。\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>引数名</th>\r\n<th>説明</th>\r\n<th>デフォルト</th>\r\n<th>必須</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>$slug</td>\r\n<td>テーマスラッグ名</td>\r\n<td>なし</td>\r\n<td>○</td>\r\n</tr>\r\n<tr>\r\n<td>$name</td>\r\n<td>特定テンプレート名</td>\r\n<td>なし</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\ncontentのpageというものを読み込んでいるらしい。\r\n合ってるかは知らないが、階層を調べていくと、\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/\r\nにある、\r\ncontent-page.php\r\nが怪しいと思われる。たぶん。\r\nちなみに\r\n(テーマ名)/templatesという中身には、\r\n本当のテンプレートがあったのでたぶんちがう。\r\n\r\nまずは公開日と更新日を返す関数をfunction.phpに追加しておきます。\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/function.php\r\nですよ。\r\n\r\n下記サイトを参考にしました。(というかそのまま頂きました・・）\r\n<a href=\"http://wispyon.com/published-modified-date/\">http://wispyon.com/published-modified-date/</a>\r\n<pre class=\"lang:php decode:true\">//更新日が投稿日より後なら返す\r\nfunction get_mtime($format) {\r\n    $mtime = get_the_modified_time(\'Ymd\');\r\n    $ptime = get_the_time(\'Ymd\');\r\n    if ($ptime &gt;= $mtime) {\r\n        return null;\r\n    } else {\r\n        return get_the_modified_time($format);\r\n    }\r\n}</pre>\r\n&lt;?php\r\nの後であればどこでもいいですが、\r\n可読性を考えて、function　～～ の並びにいれておきましょう。\r\n\r\nそして公開日時と更新日時を呼び出します。\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/content-page.php\r\nへ下記を追加します。\r\n<pre class=\"lang:xhtml decode:true \">&lt;div class=\"entry-date\"&gt;\r\n	&lt;?php if($mtime = get_mtime(\'Y.m.d\')) { ?&gt;\r\n		公開投稿日：\r\n		&lt;span itemprop=\"datePublished\" content=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" class=\"published\"&gt;\r\n		&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/span&gt;\r\n		最終更新日：\r\n		&lt;time itemprop=\"dateModified\" datetime=\"&lt;?php echo get_mtime(\'Y-m-d\') ?&gt;\" class=\"updated\"&gt;\r\n			&lt;?php echo $mtime ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } else { ?&gt;\r\n		公開日：\r\n		&lt;time itemprop=\"datePublished\" datetime=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" pubdate=\"pubdate\" class=\"published updated\"&gt;\r\n			&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } ?&gt;\r\n&lt;/div&gt;</pre>\r\n&nbsp;\r\n\r\nget_post_time(\'Y-m-d\') ・・・投稿日時を返す\r\nget_mtime(\'Y-m-d\')・・・さっき追加した公開日時を返す\r\n\r\nif文で更新日時が帰ってきたらどっちも表示して、\r\nなかったらnullなので公開日時だけ表示しますという感じです。\r\n\r\nそんでどこに追加したかというと、タイトルと記事の間、\r\nさらにヘッダーに含めたかったので、ここに入れました。\r\nテーマによって違うかもなので、参考程度に。\r\n<pre class=\"lang:xhtml decode:true \" title=\"挿入場所\">    &lt;header class=\"entry-header\"&gt;\r\n        &lt;?php     \r\n            if ( is_single() ) :\r\n            \r\n            the_title(\'&lt;h2 class=\"entry-title\"&gt;\', \'&lt;/h2&gt;\' );\r\n            \r\n            else:\r\n            \r\n            the_title( sprintf( \'&lt;h2 class=\"entry-title\"&gt;&lt;a href=\"%s\" rel=\"bookmark\"&gt;\', esc_url( get_permalink() ) ), \'&lt;/a&gt;&lt;/h2&gt;\' );\r\n            \r\n            endif; \r\n        ?&gt; \r\n\r\n&lt;!-- ここ！！！！！！！！ --&gt;\r\n\r\n    &lt;/header&gt;&lt;!-- .entry-header --&gt;\r\n\r\n    &lt;div class=\"entry-content\"&gt;\r\n       &lt;?php \r\n			the_content( \r\n				sprintf( \r\n					__( \'Read More\', \'specia\' ), \r\n					\'&lt;span class=\"screen-reader-text\"&gt;  \'.get_the_title().\'&lt;/span&gt;\' \r\n				) \r\n			);\r\n		?&gt;\r\n    &lt;/div&gt;&lt;!-- .entry-content --&gt;</pre>\r\nわからないなりにいろいろ見てみましたが、\r\nPHPの使い方がおもしろいなあと思いました。\r\nファイルがきっとクラス的な意味合いを持ってるんだろうなあ。\r\n\r\nこれから勉強して使えるようになっていきたいと思います。','WordPressに公開日と更新日を表示','','inherit','closed','closed','','185-revision-v1','','','2017-12-14 23:26:00','2017-12-14 14:26:00','',185,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/185-revision-v1/',0,'revision','',0),(275,1,'2017-12-14 23:29:27','2017-12-14 14:29:27','使っているテーマが何故か公開日も表示しないので、\n自分で直接いじって表示しました。\n\nなんだかいろいろ記事がありましたが、\nどのファイルを編集するか、\n知ってる前提で書かれてる記事が多かったので、\n分からなかった点を記載してきます。\n\n■テーマ\n/(Wordpressの置き場所)/wp-content/themes/\n\nここにWordPressのテーマが入っています。\n目的のテーマがディレクトリになっているので、その中に入ります。\n\nトップページ→index.php\n投稿ページ→single.php\nサイドナビ→sidebar.php\nテーマ専用の機能→functions.php\n\n※WordPress全体用のfunctions.phpもあるので間違えないように注意が必要\n\n今回は投稿ページを直したいので、\nsingle.phpをテキストエディタで開きます。\n\nget_template_part(\'templates/content\' \'page\')\nというものが、ページがあるだけ読み込むという処理がありました。\nこれはなんですか？\n\nget_template_part()とは？\n好きなテンプレートを読み込む関数です。\n<table>\n<thead>\n<tr>\n<th>引数名</th>\n<th>説明</th>\n<th>デフォルト</th>\n<th>必須</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>$slug</td>\n<td>テーマスラッグ名</td>\n<td>なし</td>\n<td>○</td>\n</tr>\n<tr>\n<td>$name</td>\n<td>特定テンプレート名</td>\n<td>なし</td>\n</tr>\n</tbody>\n</table>\ncontentのpageというものを読み込んでいるらしい。\n合ってるかは知らないが、階層を調べていくと、\n\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/\nにある、\ncontent-page.php\nが怪しいと思われる。たぶん。\nちなみに\n(テーマ名)/templatesという中身には、\n本当のテンプレートがあったのでたぶんちがう。\n\nまずは公開日と更新日を返す関数をfunction.phpに追加しておきます。\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/function.php\nですよ。\n\n下記サイトを参考にしました。(というかそのまま頂きました・・）\n<a href=\"http://wispyon.com/published-modified-date/\">http://wispyon.com/published-modified-date/</a>\n<pre class=\"lang:php decode:true\">//更新日が投稿日より後なら返す\nfunction get_mtime($format) {\n    $mtime = get_the_modified_time(\'Ymd\');\n    $ptime = get_the_time(\'Ymd\');\n    if ($ptime &gt;= $mtime) {\n        return null;\n    } else {\n        return get_the_modified_time($format);\n    }\n}</pre>\n&lt;?php\nの後であればどこでもいいですが、\n可読性を考えて、function　～～ の並びにいれておきましょう。\n\nそして公開日時と更新日時を呼び出します。\n\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/content-page.php\nへ下記を追加します。\n<pre class=\"lang:xhtml decode:true \">&lt;div class=\"entry-date\"&gt;\n	&lt;?php if($mtime = get_mtime(\'Y.m.d\')) { ?&gt;\n		公開投稿日：\n		&lt;span itemprop=\"datePublished\" content=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" class=\"published\"&gt;\n		&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\n		&lt;/span&gt;\n		最終更新日：\n		&lt;time itemprop=\"dateModified\" datetime=\"&lt;?php echo get_mtime(\'Y-m-d\') ?&gt;\" class=\"updated\"&gt;\n			&lt;?php echo $mtime ?&gt;\n		&lt;/time&gt;\n	&lt;?php } else { ?&gt;\n		公開日：\n		&lt;time itemprop=\"datePublished\" datetime=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" pubdate=\"pubdate\" class=\"published updated\"&gt;\n			&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\n		&lt;/time&gt;\n	&lt;?php } ?&gt;\n&lt;/div&gt;</pre>\n&nbsp;\n\nget_post_time(\'Y-m-d\') ・・・投稿日時を返す\nget_mtime(\'Y-m-d\')・・・さっき追加した公開日時を返す\n\nif文で更新日時が帰ってきたらどっちも表示して、\nなかったらnullなので公開日時だけ表示しますという感じです。\n\nそんでどこに追加したかというと、タイトルと記事の間、\nさらにヘッダーに含めたかったので、ここに入れました。\nテーマによって違うかもなので、参考程度に。\n<pre class=\"lang:xhtml decode:true\" title=\"挿入場所\">    &lt;header class=\"entry-header\"&gt;\n        &lt;?php     \n            if ( is_single() ) :\n            \n            the_title(\'&lt;h2 class=\"entry-title\"&gt;\', \'&lt;/h2&gt;\' );\n            \n            else:\n            \n            the_title( sprintf( \'&lt;h2 class=\"entry-title\"&gt;&lt;a href=\"%s\" rel=\"bookmark\"&gt;\', esc_url( get_permalink() ) ), \'&lt;/a&gt;&lt;/h2&gt;\' );\n            \n            endif; \n        ?&gt; \n\n&lt;!-- ★☆★ここ！！！！！！！！★☆★ --&gt;\n\n    &lt;/header&gt;&lt;!-- .entry-header --&gt;\n\n    &lt;div class=\"entry-content\"&gt;\n       &lt;?php \n			the_content( \n				sprintf( \n					__( \'Read More\', \'specia\' ), \n					\'&lt;span class=\"screen-reader-text\"&gt;  \'.get_the_title().\'&lt;/span&gt;\' \n				) \n			);\n		?&gt;\n    &lt;/div&gt;&lt;!-- .entry-content --&gt;</pre>\n&nbsp;\n\n&nbsp;\n\nわからないなりにいろいろ見てみましたが、\nPHPの使い方がおもしろいなあと思いました。\nファイルがきっとクラス的な意味合いを持ってるんだろうなあ。\n\nこれから勉強して使えるようになっていきたいと思います。','WordPressに公開日と更新日を表示','','inherit','closed','closed','','185-autosave-v1','','','2017-12-14 23:29:27','2017-12-14 14:29:27','',185,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/185-autosave-v1/',0,'revision','',0),(276,1,'2017-12-14 23:31:00','2017-12-14 14:31:00','使っているテーマが何故か公開日も表示しないので、\r\n自分で直接いじって表示しました。\r\n\r\nなんだかいろいろ記事がありましたが、\r\nどのファイルを編集するか、\r\n知ってる前提で書かれてる記事が多かったので、\r\n分からなかった点を記載してきます。\r\n\r\n■テーマ\r\n/(Wordpressの置き場所)/wp-content/themes/\r\n\r\nここにWordPressのテーマが入っています。\r\n目的のテーマがディレクトリになっているので、その中に入ります。\r\n\r\nトップページ→index.php\r\n投稿ページ→single.php\r\nサイドナビ→sidebar.php\r\nテーマ専用の機能→functions.php\r\n\r\n※WordPress全体用のfunctions.phpもあるので間違えないように注意が必要\r\n\r\n今回は投稿ページを直したいので、\r\nsingle.phpをテキストエディタで開きます。\r\n\r\nget_template_part(\'templates/content\' \'page\')\r\nというものが、ページがあるだけ読み込むという処理がありました。\r\nこれはなんですか？\r\n\r\nget_template_part()とは？\r\n好きなテンプレートを読み込む関数です。\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>引数名</th>\r\n<th>説明</th>\r\n<th>デフォルト</th>\r\n<th>必須</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>$slug</td>\r\n<td>テーマスラッグ名</td>\r\n<td>なし</td>\r\n<td>○</td>\r\n</tr>\r\n<tr>\r\n<td>$name</td>\r\n<td>特定テンプレート名</td>\r\n<td>なし</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\ncontentのpageというものを読み込んでいるらしい。\r\n合ってるかは知らないが、階層を調べていくと、\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/\r\nにある、\r\ncontent-page.php\r\nが怪しいと思われる。たぶん。\r\nちなみに\r\n(テーマ名)/templatesという中身には、\r\n本当のテンプレートがあったのでたぶんちがう。\r\n\r\nまずは公開日と更新日を返す関数をfunction.phpに追加しておきます。\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/function.php\r\nですよ。\r\n\r\n下記サイトを参考にしました。(というかそのまま頂きました・・）\r\n<a href=\"http://wispyon.com/published-modified-date/\">http://wispyon.com/published-modified-date/</a>\r\n<pre class=\"lang:php decode:true\">//更新日が投稿日より後なら返す\r\nfunction get_mtime($format) {\r\n    $mtime = get_the_modified_time(\'Ymd\');\r\n    $ptime = get_the_time(\'Ymd\');\r\n    if ($ptime &gt;= $mtime) {\r\n        return null;\r\n    } else {\r\n        return get_the_modified_time($format);\r\n    }\r\n}</pre>\r\n&lt;?php\r\nの後であればどこでもいいですが、\r\n可読性を考えて、function　～～ の並びにいれておきましょう。\r\n\r\nそして公開日時と更新日時を呼び出します。\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/content-page.php\r\nへ下記を追加します。\r\n<pre class=\"lang:xhtml decode:true \">&lt;div class=\"entry-date\"&gt;\r\n	&lt;?php if($mtime = get_mtime(\'Y.m.d\')) { ?&gt;\r\n		公開投稿日：\r\n		&lt;span itemprop=\"datePublished\" content=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" class=\"published\"&gt;\r\n		&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/span&gt;\r\n		最終更新日：\r\n		&lt;time itemprop=\"dateModified\" datetime=\"&lt;?php echo get_mtime(\'Y-m-d\') ?&gt;\" class=\"updated\"&gt;\r\n			&lt;?php echo $mtime ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } else { ?&gt;\r\n		公開日：\r\n		&lt;time itemprop=\"datePublished\" datetime=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" pubdate=\"pubdate\" class=\"published updated\"&gt;\r\n			&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } ?&gt;\r\n&lt;/div&gt;</pre>\r\n&nbsp;\r\n\r\nget_post_time(\'Y-m-d\') ・・・投稿日時を返す\r\nget_mtime(\'Y-m-d\')・・・さっき追加した公開日時を返す\r\n\r\nif文で更新日時が帰ってきたらどっちも表示して、\r\nなかったらnullなので公開日時だけ表示しますという感じです。\r\n\r\nそんでどこに追加したかというと、タイトルと記事の間、\r\nさらにヘッダーに含めたかったので、ここに入れました。\r\nテーマによって違うかもなので、参考程度に。\r\n<pre class=\"lang:xhtml decode:true\" title=\"挿入場所\">    &lt;header class=\"entry-header\"&gt;\r\n        &lt;?php     \r\n            if ( is_single() ) :\r\n            \r\n            the_title(\'&lt;h2 class=\"entry-title\"&gt;\', \'&lt;/h2&gt;\' );\r\n            \r\n            else:\r\n            \r\n            the_title( sprintf( \'&lt;h2 class=\"entry-title\"&gt;&lt;a href=\"%s\" rel=\"bookmark\"&gt;\', esc_url( get_permalink() ) ), \'&lt;/a&gt;&lt;/h2&gt;\' );\r\n            \r\n            endif; \r\n        ?&gt; \r\n\r\n&lt;!-- ★☆★ここ！！！！！！！！★☆★ --&gt;\r\n\r\n    &lt;/header&gt;&lt;!-- .entry-header --&gt;\r\n\r\n    &lt;div class=\"entry-content\"&gt;\r\n       &lt;?php \r\n			the_content( \r\n				sprintf( \r\n					__( \'Read More\', \'specia\' ), \r\n					\'&lt;span class=\"screen-reader-text\"&gt;  \'.get_the_title().\'&lt;/span&gt;\' \r\n				) \r\n			);\r\n		?&gt;\r\n    &lt;/div&gt;&lt;!-- .entry-content --&gt;</pre>\r\n&nbsp;\r\n\r\n<span class=\"crayon-r \">&lt;header </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-header\"</span><span class=\"crayon-r \">&gt;\r\n&lt;/header&gt;\r\n</span>の一番最後にいれました。\r\nその次のタグが\r\n<span class=\"crayon-r \">&lt;div </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-content\"</span><span class=\"crayon-r \">&gt;</span>\r\nなので、記事の内容は始まってしまいますからね。\r\n\r\n&nbsp;\r\n\r\nわからないなりにいろいろ見てみましたが、\r\nPHPの使い方がおもしろいなあと思いました。\r\nファイルがきっとクラス的な意味合いを持ってるんだろうなあ。\r\n\r\n&nbsp;\r\n\r\nこれから勉強して使えるようになっていきたいと思います。','WordPressに公開日と更新日を表示','','inherit','closed','closed','','185-revision-v1','','','2017-12-14 23:31:00','2017-12-14 14:31:00','',185,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/185-revision-v1/',0,'revision','',0),(277,1,'2017-12-14 23:33:49','2017-12-14 14:33:49','使っているテーマが何故か公開日も表示しないので、\r\n自分で直接いじって表示しました。\r\n\r\nなんだかいろいろ記事がありましたが、\r\nどのファイルを編集するか、\r\n知ってる前提で書かれてる記事が多かったので、\r\n分からなかった点を記載してきます。\r\n\r\n■テーマ\r\n/(Wordpressの置き場所)/wp-content/themes/\r\n\r\nここにWordPressのテーマが入っています。\r\n目的のテーマがディレクトリになっているので、その中に入ります。\r\n\r\nトップページ→index.php\r\n投稿ページ→single.php\r\nサイドナビ→sidebar.php\r\nテーマ専用の機能→functions.php\r\n\r\n※WordPress全体用のfunctions.phpもあるので間違えないように注意が必要\r\n\r\n今回は投稿ページを直したいので、\r\nsingle.phpをテキストエディタで開きます。\r\n\r\nget_template_part(\'templates/content\' \'page\')\r\nというものが、ページがあるだけ読み込むという処理がありました。\r\nこれはなんですか？\r\n\r\nget_template_part()とは？\r\n好きなテンプレートを読み込む関数です。\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>引数名</th>\r\n<th>説明</th>\r\n<th>デフォルト</th>\r\n<th>必須</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>$slug</td>\r\n<td>テーマスラッグ名</td>\r\n<td>なし</td>\r\n<td>○</td>\r\n</tr>\r\n<tr>\r\n<td>$name</td>\r\n<td>特定テンプレート名</td>\r\n<td>なし</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\ncontentのpageというものを読み込んでいるらしい。\r\n合ってるかは知らないが、階層を調べていくと、\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/\r\nにある、\r\ncontent-page.php\r\nが怪しいと思われる。たぶん。\r\nちなみに\r\n(テーマ名)/templatesという中身には、\r\n本当のテンプレートがあったのでたぶんちがう。\r\n\r\nまずは公開日と更新日を返す関数をfunction.phpに追加しておきます。\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/function.php\r\nですよ。\r\n\r\n下記サイトを参考にしました。(というかそのまま頂きました・・）\r\n<a href=\"http://wispyon.com/published-modified-date/\">http://wispyon.com/published-modified-date/</a>\r\n<pre class=\"lang:php decode:true\">//更新日が投稿日より後なら返す\r\nfunction get_mtime($format) {\r\n    $mtime = get_the_modified_time(\'Ymd\');\r\n    $ptime = get_the_time(\'Ymd\');\r\n    if ($ptime &gt;= $mtime) {\r\n        return null;\r\n    } else {\r\n        return get_the_modified_time($format);\r\n    }\r\n}</pre>\r\n&lt;?php\r\nの後であればどこでもいいですが、\r\n可読性を考えて、function　～～ の並びにいれておきましょう。\r\n\r\nそして公開日時と更新日時を呼び出します。\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/content-page.php\r\nへ下記を追加します。\r\n<pre class=\"lang:xhtml decode:true \">&lt;div class=\"entry-date\"&gt;\r\n	&lt;?php if($mtime = get_mtime(\'Y.m.d\')) { ?&gt;\r\n		公開投稿日：\r\n		&lt;span itemprop=\"datePublished\" content=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" class=\"published\"&gt;\r\n		&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/span&gt;\r\n		最終更新日：\r\n		&lt;time itemprop=\"dateModified\" datetime=\"&lt;?php echo get_mtime(\'Y-m-d\') ?&gt;\" class=\"updated\"&gt;\r\n			&lt;?php echo $mtime ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } else { ?&gt;\r\n		公開日：\r\n		&lt;time itemprop=\"datePublished\" datetime=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" pubdate=\"pubdate\" class=\"published updated\"&gt;\r\n			&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } ?&gt;\r\n&lt;/div&gt;</pre>\r\n&nbsp;\r\n\r\nget_post_time(\'Y-m-d\') ・・・投稿日時を返す\r\nget_mtime(\'Y-m-d\')・・・さっき追加した公開日時を返す\r\n\r\nif文で更新日時が帰ってきたらどっちも表示して、\r\nなかったらnullなので公開日時だけ表示しますという感じです。\r\n\r\nそんでどこに追加したかというと、タイトルと記事の間、\r\nさらにヘッダーに含めたかったので、ここに入れました。\r\nテーマによって違うかもなので、参考程度に。\r\n<pre class=\"lang:xhtml decode:true \" title=\"挿入場所\">    &lt;header class=\"entry-header\"&gt;\r\n        &lt;?php     \r\n            if ( is_single() ) :\r\n            \r\n            the_title(\'&lt;h2 class=\"entry-title\"&gt;\', \'&lt;/h2&gt;\' );\r\n            \r\n            else:\r\n            \r\n            the_title( sprintf( \'&lt;h2 class=\"entry-title\"&gt;&lt;a href=\"%s\" rel=\"bookmark\"&gt;\', esc_url( get_permalink() ) ), \'&lt;/a&gt;&lt;/h2&gt;\' );\r\n            \r\n            endif; \r\n        ?&gt; \r\n\r\n&lt;!-- ★☆★☆★☆★☆★☆★☆★★☆★ --&gt;\r\n&lt;!-- ★☆★ここ！！！！！！！！★☆★ --&gt;\r\n&lt;!-- ★☆★☆★☆★☆★☆★☆★★☆★ --&gt;\r\n\r\n    &lt;/header&gt;&lt;!-- .entry-header --&gt;\r\n\r\n    &lt;div class=\"entry-content\"&gt;\r\n       &lt;?php \r\n			the_content( \r\n				sprintf( \r\n					__( \'Read More\', \'specia\' ), \r\n					\'&lt;span class=\"screen-reader-text\"&gt;  \'.get_the_title().\'&lt;/span&gt;\' \r\n				) \r\n			);\r\n		?&gt;\r\n    &lt;/div&gt;&lt;!-- .entry-content --&gt;</pre>\r\n&nbsp;\r\n\r\n<span class=\"crayon-r \">&lt;header </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-header\"</span><span class=\"crayon-r \">&gt;\r\n&lt;/header&gt;\r\n</span>の一番最後にいれました。\r\nその次のタグが\r\n<span class=\"crayon-r \">&lt;div </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-content\"</span><span class=\"crayon-r \">&gt;</span>\r\nなので、記事の内容は始まってしまいますからね。\r\n\r\n&nbsp;\r\n\r\nわからないなりにいろいろ見てみましたが、\r\nPHPの使い方がおもしろいなあと思いました。\r\nファイルがきっとクラス的な意味合いを持ってるんだろうなあ。\r\n\r\n&nbsp;\r\n\r\nこれから勉強して使えるようになっていきたいと思います。','WordPressに公開日と更新日を表示','','inherit','closed','closed','','185-revision-v1','','','2017-12-14 23:33:49','2017-12-14 14:33:49','',185,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/185-revision-v1/',0,'revision','',0),(278,1,'2017-12-14 23:37:50','2017-12-14 14:37:50','<span style=\"color: #747474; font-family: \'Open Sans\', sans-serif; font-size: 14px;\">#06 擬似クラスを使ってみよう</span>\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31706\">https://dotinstall.com/lessons/basic_css_v3/31706</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/06/\">http://www.tmotoki.net/static/dot_install/02_css/06/</a>\r\n\r\n■メモ\r\n疑似クラスとは、htmlで指定しなくてもあらかじめ決まっているもの。\r\nたとえば、あるタグの1つ目の子供に対してスタイルをつけたい場合は、\r\nfirst-childをつけるなど。\r\n\r\n:（コロン）でタグの後ろに指定する。\r\n指定する順番にも注意すること。\r\njavascriptとかを使わなくてもここまでできるんだね。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n セレクタ\r\n 疑似クラス\r\n*/\r\n\r\n/* ulタグの子liの1つ目 */\r\n/* css3では2つ目、最後といった指定もできる */\r\nul li:first-child { color:skyblue; }\r\n\r\n\r\n/* \r\n aタグにはこの順番で指定しないと、\r\n 正しく反映されない可能性もある。\r\n*/\r\n\r\na:link { color: violet; }		/* 未訪問 */\r\na:visited { color: orange; }	/* 訪問済 */\r\na:hover { color: pink; }		/* マウスを上に乗せる */\r\na:active { color: red; }		/* クリック */\r\n\r\n/* カーソルがinputタグにある場合 */\r\ninput:focus { background: skyblue;}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;ul&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n			&lt;li&gt;うまい&lt;/li&gt;\r\n		&lt;/ul&gt;\r\n		&lt;p&gt;\r\n			&lt;a href=\"http://dotinstall.com\"&gt;\r\n				Dotinstall\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;a href=\"http://yahoo.com\"&gt;\r\n				Yahoo\r\n			&lt;/a&gt;\r\n		&lt;/p&gt;\r\n		\r\n		&lt;p&gt;\r\n			&lt;input type=\"text\"&gt;\r\n		&lt;/p&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #06(ドットインストール)','','inherit','closed','closed','','248-revision-v1','','','2017-12-14 23:37:50','2017-12-14 14:37:50','',248,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/248-revision-v1/',0,'revision','',0),(279,1,'2017-12-14 23:42:09','2017-12-14 14:42:09','使っているテーマが何故か公開日も表示しないので、\r\n自分で直接いじって表示しました。\r\n\r\nなんだかいろいろ記事がありましたが、\r\nどのファイルを編集するか、\r\n知ってる前提で書かれてる記事が多かったので、\r\n分からなかった点を記載してきます。\r\n\r\n■テーマ\r\n/(Wordpressの置き場所)/wp-content/themes/\r\n\r\nここにWordPressのテーマが入っています。\r\n目的のテーマがディレクトリになっているので、その中に入ります。\r\n\r\nトップページ→index.php\r\n投稿ページ→single.php\r\nサイドナビ→sidebar.php\r\nテーマ専用の機能→functions.php\r\n\r\n※WordPress全体用のfunctions.phpもあるので間違えないように注意が必要\r\n\r\n今回は投稿ページを直したいので、\r\nsingle.phpをテキストエディタで開きます。\r\n\r\nget_template_part(\'templates/content\' \'page\')\r\nというものが、ページがあるだけ読み込むという処理がありました。\r\nこれはなんですか？\r\n\r\nget_template_part()とは？\r\n好きなテンプレートを読み込む関数です。\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>引数名</th>\r\n<th>説明</th>\r\n<th>デフォルト</th>\r\n<th>必須</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>$slug</td>\r\n<td>テーマスラッグ名</td>\r\n<td>なし</td>\r\n<td>○</td>\r\n</tr>\r\n<tr>\r\n<td>$name</td>\r\n<td>特定テンプレート名</td>\r\n<td>なし</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\ncontentのpageというものを読み込んでいるらしい。\r\n合ってるかは知らないが、階層を調べていくと、\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/\r\nにある、\r\ncontent-page.php\r\nが怪しいと思われる。たぶん。\r\nちなみに\r\n(テーマ名)/templatesという中身には、\r\n本当のテンプレートがあったのでたぶんちがう。\r\n\r\nまずは公開日と更新日を返す関数をfunction.phpに追加しておきます。\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/function.php\r\nですよ。\r\n\r\n下記サイトを参考にしました。(というかそのまま頂きました・・）\r\n<a href=\"http://wispyon.com/published-modified-date/\">http://wispyon.com/published-modified-date/</a>\r\n<pre class=\"lang:php decode:true\">//更新日が投稿日より後なら返す\r\nfunction get_mtime($format) {\r\n    $mtime = get_the_modified_time(\'Ymd\');\r\n    $ptime = get_the_time(\'Ymd\');\r\n    if ($ptime &gt;= $mtime) {\r\n        return null;\r\n    } else {\r\n        return get_the_modified_time($format);\r\n    }\r\n}</pre>\r\n&lt;?php\r\nの後であればどこでもいいですが、\r\n可読性を考えて、function　～～ の並びにいれておきましょう。\r\n\r\nそして公開日時と更新日時を呼び出します。\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/content-page.php\r\nへ下記を追加します。\r\n<pre class=\"lang:xhtml decode:true \">&lt;div class=\"entry-date\"&gt;\r\n	&lt;?php if($mtime = get_mtime(\'Y.m.d\')) { ?&gt;\r\n		公開投稿日：\r\n		&lt;span itemprop=\"datePublished\" content=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" class=\"published\"&gt;\r\n		&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/span&gt;\r\n		最終更新日：\r\n		&lt;time itemprop=\"dateModified\" datetime=\"&lt;?php echo get_mtime(\'Y-m-d\') ?&gt;\" class=\"updated\"&gt;\r\n			&lt;?php echo $mtime ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } else { ?&gt;\r\n		公開日：\r\n		&lt;time itemprop=\"datePublished\" datetime=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" pubdate=\"pubdate\" class=\"published updated\"&gt;\r\n			&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } ?&gt;\r\n&lt;/div&gt;</pre>\r\n&nbsp;\r\n\r\nget_post_time(\'Y-m-d\') ・・・投稿日時を返す\r\nget_mtime(\'Y-m-d\')・・・さっき追加した公開日時を返す\r\n\r\nif文で更新日時が帰ってきたらどっちも表示して、\r\nなかったらnullなので公開日時だけ表示しますという感じです。\r\n\r\nそんでどこに追加したかというと、タイトルと記事の間、\r\nさらにヘッダーに含めたかったので、ここに入れました。\r\nテーマによって違うかもなので、参考程度に。\r\n<pre class=\"lang:xhtml decode:true \" title=\"挿入場所\">    &lt;header class=\"entry-header\"&gt;\r\n        &lt;?php     \r\n            if ( is_single() ) :\r\n            \r\n            the_title(\'&lt;h2 class=\"entry-title\"&gt;\', \'&lt;/h2&gt;\' );\r\n            \r\n            else:\r\n            \r\n            the_title( sprintf( \'&lt;h2 class=\"entry-title\"&gt;&lt;a href=\"%s\" rel=\"bookmark\"&gt;\', esc_url( get_permalink() ) ), \'&lt;/a&gt;&lt;/h2&gt;\' );\r\n            \r\n            endif; \r\n        ?&gt; \r\n\r\n&lt;!-- ★☆★☆★☆★☆★☆★☆★★☆★ --&gt;\r\n&lt;!-- ★☆★ここ！！！！！！！！★☆★ --&gt;\r\n&lt;!-- ★☆★☆★☆★☆★☆★☆★★☆★ --&gt;\r\n\r\n    &lt;/header&gt;&lt;!-- .entry-header --&gt;\r\n\r\n    &lt;div class=\"entry-content\"&gt;\r\n       &lt;?php \r\n			the_content( \r\n				sprintf( \r\n					__( \'Read More\', \'specia\' ), \r\n					\'&lt;span class=\"screen-reader-text\"&gt;  \'.get_the_title().\'&lt;/span&gt;\' \r\n				) \r\n			);\r\n		?&gt;\r\n    &lt;/div&gt;&lt;!-- .entry-content --&gt;</pre>\r\n&nbsp;\r\n\r\n<span class=\"crayon-r \">&lt;header </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-header\"</span><span class=\"crayon-r \">&gt;\r\n&lt;/header&gt;\r\n</span>の一番最後にいれました。\r\nその次のタグが\r\n<span class=\"crayon-r \">&lt;div </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-content\"</span><span class=\"crayon-r \">&gt;</span>\r\nなので、記事の内容は始まってしまいますからね。\r\n\r\n&nbsp;\r\n\r\nわからないなりにいろいろ見てみましたが、\r\nPHPの使い方がおもしろいなあと思いました。\r\nファイルがきっとクラス的な意味合いを持ってるんだろうなあ。\r\n\r\n&nbsp;\r\n\r\nこれから勉強して使えるようになっていきたいと思います。\r\n\r\n&nbsp;\r\n\r\n■追記\r\n\r\n下記にも同じように挿入してやらないと、\r\n一部のページで日時が表示されませんでした。\r\n\r\ncontent.php\r\ncontent-search.php','WordPressに公開日と更新日を表示','','inherit','closed','closed','','185-revision-v1','','','2017-12-14 23:42:09','2017-12-14 14:42:09','',185,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/185-revision-v1/',0,'revision','',0),(280,1,'2017-12-14 23:45:41','2017-12-14 14:45:41','AWS EC2はIaasです。\r\nOSの起動までは非常に簡単ですが、\r\nそこから設定は自分でしなければなりません。\r\n\r\n事前準備として、\r\n「静的なグローバルIP取得」、「ドメイン取得」があります。\r\nまた機会があればそれも記事にしたいと思います。\r\n\r\nまた今回利用しているOSは、Amazon Linuxです。\r\nほとんどCentOSですが、yumに登録されているアプリが、\r\n本家CentOSと異なる点に注意が必要です。\r\n\r\nそれではまずWebサーバを立てます。\r\n\r\n今回は一番有名なApacheサーバを利用します。\r\n今後はもしかしたらNginXにするかもしれません。\r\n（有名になるか、やる気になるか）\r\n\r\n１．インストール（コマンド一発）\r\n<pre class=\"lang:sh decode:true \">$ sudo yum install httpd</pre>\r\n２．OS起動時、常に開始するようにする\r\n<pre class=\"lang:sh decode:true \">$ sudo chkconfig httpd on</pre>\r\n３．サービスを確認する\r\n<pre class=\"lang:sh decode:true \">$ chkconfig | grep httpd</pre>\r\n<img class=\"alignnone size-full wp-image-36\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00001.png\" alt=\"\" width=\"564\" height=\"19\" />\r\n※3がonならOK。\r\n\r\n４．サービスを開始する\r\n<pre class=\"lang:sh decode:true \">$ sudo /etc/init.d/httpd start</pre>\r\n<img class=\"alignnone size-full wp-image-37\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00002.png\" alt=\"\" width=\"897\" height=\"434\" />\r\n\r\nあとは/var/www/html配下に、\r\n好きなファイルを置けば、Webコンテンツになり、\r\nアクセスできるようになります。','WordPressの導入①　～Webサーバを立てる～','','inherit','closed','closed','','35-revision-v1','','','2017-12-14 23:45:41','2017-12-14 14:45:41','',35,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/35-revision-v1/',0,'revision','',0),(281,1,'2017-12-14 23:47:40','2017-12-14 14:47:40','以前受けたセミナーで習ったこと。\r\n\r\n①パーマリンク設定\r\nカスタム構造に下記を入力\r\n/%category%/%postname%/\r\n\r\n→URLが分かりやすく短くなるよ。デフォルトだと長いですよ。\r\n\r\n②プラグイン設定\r\n設定\r\n・Hello Dollyを削除\r\n・Akismet有効化→APIキー登録\r\n・WP Multibyte Patchを有効化\r\n新規インストール\r\n・BackWPup(自動バックアップ)\r\n・Login rebuilder(管理画面ログインURL変更)\r\n・Show Current Template(どのテンプレートを使っているか表示)\r\n\r\n■APIキーの登録\r\nなんか手順違うかったけど一応のせとこう。\r\nhttps://whitehatseo.jp/setup-of-akismet/\r\nあなたが値段決めてね言われるので、0にする。\r\n（いやな顔をされる）\r\n\r\n■WP Multibyte Patchを利用するにはPHP の mbstring 関数が必要\r\n<pre class=\"lang:sh decode:true \"># sudo yum -y install php-mbstring\r\n# sudo service httpd restart</pre>\r\nインストールして、Apacheサーバを再起動して、はい終わり。\r\n\r\n新規追加は、新規追加ボタンを押して、\r\n検索ウィンドウで検索したら、出てくるのでインストールして有効化するだけ。\r\n\r\nShow Current Templateは何使ってるか見れるようになるので便利。\r\nバックアップはもしもの為ですね。\r\nログインURLの変更はセキュリティ対策です。\r\nURLを変えることによって、\r\nアタック回数が激減する（といいいな）と言われています。','WordPressで最初にすること','','inherit','closed','closed','','94-revision-v1','','','2017-12-14 23:47:40','2017-12-14 14:47:40','',94,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/94-revision-v1/',0,'revision','',0),(282,1,'2017-12-14 23:51:01','2017-12-14 14:51:01','WordPressに必要な環境は下記です。\r\n<ul>\r\n 	<li>Apache(インストール済み)</li>\r\n 	<li>MySQL</li>\r\n 	<li>PHP</li>\r\n</ul>\r\nWebサーバはWebページや画像などをUPする場所、\r\nMySQLは投稿した記事などの情報の蓄積、\r\nPHPはそれらの動作をするための実行環境です。\r\n\r\nそれでは作業しましょう。\r\n<ol>\r\n 	<li>インストール（Apache以外)\r\n<pre class=\"lang:sh decode:true \">$ sudo yum install mysql-server php php-mysql wget\r\n</pre>\r\n一撃です。\r\nwgetはダウンロード用のコマンドなので入れときます。\r\nphp-mysqlはphpからMySQLを操作する為に必要です。\r\n（たぶんデフォルトで入っていると思うが念のため）</li>\r\n 	<li>phpの時刻を日本時間にする\r\n<pre class=\"lang:sh decode:true\">sudo cp /etc/php.ini /etc/php.ini.org\r\nsudo vi /etc/php.ini</pre>\r\n----------------------------------\r\n<em>date.timezone = \"Asia/Tokyo\"</em>\r\n----------------------------------\r\n※設定ファイルを念のためバックアップして、編集します。</li>\r\n 	<li>設定を反映する（Apacheの再起動）\r\n<pre class=\"lang:sh decode:true\">sudo /etc/init.d/httpd restart</pre>\r\n</li>\r\n 	<li>php確認用のページを作る\r\n<pre class=\"lang:sh decode:true\">sudo touch /var/www/html/phpinfo.php\r\nsudo vi /var/www/html/phpinfo.php</pre>\r\n---------------------------------\r\n<em>&lt;?php</em>\r\n<em> phpinfo();</em>\r\n<em> ?&gt;</em>\r\n---------------------------------\r\nphpinfo.phpをWebサーバのフォルダへ作り、\r\nphpの情報を出力するプログラムを記述する。</li>\r\n 	<li>該当ページにアクセスして、phpの情報を確認する\r\n<img class=\"alignnone size-full wp-image-45\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00003.png\" alt=\"\" width=\"614\" height=\"927\" />\r\n※設定をミスっている、Apacheを再起動してない場合、\r\n上記画面ではなく、プログラムがそのまま表示されます。\r\n（テキストデータのように）</li>\r\n</ol>','WordPress導入② ～実行環境を整える～','','inherit','closed','closed','','42-revision-v1','','','2017-12-14 23:51:01','2017-12-14 14:51:01','',42,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/42-revision-v1/',0,'revision','',0),(283,1,'2017-12-14 23:54:48','2017-12-14 14:54:48','WordPressは投稿された記事などを、\nDBに保存していきます。\n\nmarinaDBなどいろいろ対応しているようですが、\n今回は普通にMySQLにしていきたいと思います。\n<ol>\n 	<li>MySQLサービスを開始する\n<pre class=\"lang:sh decode:true \">$ sudo /etc/init.d/mysqld start\n</pre>\n</li>\n 	<li>本当に起動できたか確認する\n<pre class=\"lang:sh decode:true \">mysqladmin -u root pin</pre>\n-----------------------\nmysqld is alive\n-----------------------\n※aliveになっていればOK。\nちなみにmysqldの最後のdはデーモンという意味。\n（デーモン = バックグラウンドで動作中のアプリケーション)</li>\n 	<li>上記起動設定にする\n<pre class=\"lang:sh decode:true\">$ sudo chkconfig mysqld on\n$ chkconfig | grep mysqld</pre>\n<img class=\"alignnone size-full wp-image-50\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00004.png\" alt=\"\" width=\"567\" height=\"13\" />\n※3がonならOK</li>\n 	<li>MySQLのrootユーザにパスワードを設定する\n<pre class=\"lang:sh decode:true\">$ mysql -u root</pre>\n----------------------------------------------\n<pre class=\"lang:mysql decode:true\">mysql&gt; update mysql.user set password=password(\'任意のパスワード\') where user = \'root\';\nmysql&gt; flush privileges; ← 変更を反映\nmysql&gt; exit;</pre>\n----------------------------------------------\n※外部公開はしない予定だが、\n万が一の可能性を考慮して設定</li>\n 	<li>WordPress専用のデータベースを作成する\n<strong>$ mysql -u root -p</strong>\n--------------------------------------------\nmysql&gt; create database wp;\nmysql&gt; grant all privileges on wp.* to wp@localhost identified by \'任意のパスワード\';\nmysql&gt; exit;\n--------------------------------------------\n※wpというデータベースに、\nwpとうユーザを作り、任意のパスワードを設定</li>\n</ol>','WordPressの導入③　～MySQLに専用のDBを作る～','','inherit','closed','closed','','49-autosave-v1','','','2017-12-14 23:54:48','2017-12-14 14:54:48','',49,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/49-autosave-v1/',0,'revision','',0),(284,1,'2017-12-14 23:55:48','2017-12-14 14:55:48','WordPressは投稿された記事などを、\r\nDBに保存していきます。\r\n\r\nmarinaDBなどいろいろ対応しているようですが、\r\n今回は普通にMySQLにしていきたいと思います。\r\n<ol>\r\n 	<li>MySQLサービスを開始する\r\n<pre class=\"lang:sh decode:true \">$ sudo /etc/init.d/mysqld start\r\n</pre>\r\n</li>\r\n 	<li>本当に起動できたか確認する\r\n<pre class=\"lang:sh decode:true \">mysqladmin -u root pin</pre>\r\n-----------------------\r\nmysqld is alive\r\n-----------------------\r\n※aliveになっていればOK。\r\nちなみにmysqldの最後のdはデーモンという意味。\r\n（デーモン = バックグラウンドで動作中のアプリケーション)</li>\r\n 	<li>上記起動設定にする\r\n<pre class=\"lang:sh decode:true\">$ sudo chkconfig mysqld on\r\n$ chkconfig | grep mysqld</pre>\r\n<img class=\"alignnone size-full wp-image-50\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00004.png\" alt=\"\" width=\"567\" height=\"13\" />\r\n※3がonならOK</li>\r\n 	<li>MySQLのrootユーザにパスワードを設定する\r\n<pre class=\"lang:sh decode:true\">$ mysql -u root</pre>\r\n----------------------------------------------\r\n<pre class=\"lang:mysql decode:true\">mysql&gt; update mysql.user set password=password(\'任意のパスワード\') where user = \'root\';\r\nmysql&gt; flush privileges; ← 変更を反映\r\nmysql&gt; exit;</pre>\r\n----------------------------------------------\r\n※外部公開はしない予定だが、\r\n万が一の可能性を考慮して設定</li>\r\n 	<li>WordPress専用のデータベースを作成する\r\n<pre class=\"lang:sh decode:true \">$ mysql -u root -p</pre>\r\n--------------------------------------------\r\n<pre class=\"lang:mysql decode:true \">mysql&gt; create database wp;\r\nmysql&gt; grant all privileges on wp.* to wp@localhost identified by \'任意のパスワード\';\r\nmysql&gt; exit;</pre>\r\n--------------------------------------------\r\n※wpというデータベースに、\r\nwpとうユーザを作り、任意のパスワードを設定</li>\r\n</ol>','WordPressの導入③　～MySQLに専用のDBを作る～','','inherit','closed','closed','','49-revision-v1','','','2017-12-14 23:55:48','2017-12-14 14:55:48','',49,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/49-revision-v1/',0,'revision','',0),(285,1,'2017-12-14 23:59:36','2017-12-14 14:59:36','いよいよWordPressをインストールします。\r\n\r\nWordPressのバージョンは\r\n<a href=\"http://ja.wordpress.org/releases/\" target=\"_blank\" rel=\"noopener noreferrer\">http://ja.wordpress.org/releases/</a>で確認してください。\r\n<ol>\r\n 	<li>Wordpressを取得して、Webサーバに配置する\r\n<pre class=\"lang:sh decode:true \">$ mkdir tmp\r\n$ cd tmp\r\n$ wget http://ja.wordpress.org/wordpress-4.7.5-ja.tar.gz\r\n$ tar zxvf wordpress-4.7.5-ja.tar.gz\r\n$ sudo cp -r wordpress /var/www/\r\n$ sudo chown -R ec2-user:ec2-user /var/www/wordpress\r\n</pre>\r\n任意のディレクトリを作り、\r\nWordPressをダウンロード(バージョンは適宜変更)。\r\n解凍してApacheのディレクトリへ移動します。最後にec2-userユーザが操作できるように、\r\nwordpress配下の全ファイルとディレクトリの権限を、\r\nec2-userユーザに指定しています。</li>\r\n 	<li>ApacheのDocumentRootをWordpressに変更する\r\n<pre class=\"lang:sh decode:true \">$ sudo cp /etc/httpd/conf/httpd.conf /etc/httpd/conf/httpd.conf.org\r\n$ sudo vi /etc/httpd/conf/httpd.conf</pre>\r\n-------------------------------------------------------------\r\nDocumentRoot \"/var/www/wordpress\"\r\n&lt;Directory \"/var/www/wordpress\"&gt;\r\nAllowOverride All\r\n-------------------------------------------------------------\r\n<pre class=\"lang:sh decode:true \">$ sudo /etc/init.d/httpd restart\r\n</pre>\r\n念のためバックアップをとったあと、\r\nDocumentRootとDirectoryを\"/var/www/wordpress\"に変更します。\r\n※1箇所しかないのでわかるはず。\r\nAllowOverride ALLは、\r\n.htaccessによるディレクティブの上書きを許可しています。</li>\r\n 	<li>ゲストの権限に書き込みを追加する\r\n<pre class=\"lang:sh decode:true \">$ sudo chmod -R 757 /var/www/wordpress\r\n$ sudo chmod -R 757 /var/www/wordpress/wp-content/</pre>\r\n<strong>\r\n</strong>これをしておかないと、ブラウザから操作しても受け付けず、\r\nテーマのインストールすらできない。\r\nwordpressディレクトリとその配下の、\r\nwp-contentディレクトリは必ず設定しておく。<img class=\"alignnone size-full wp-image-58\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00005.png\" alt=\"\" width=\"483\" height=\"106\" />\r\n\r\n<img class=\"alignnone size-full wp-image-59\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/05/00006.png\" alt=\"\" width=\"581\" height=\"334\" /></li>\r\n 	<li>WordpressをインストールするWebサーバのURLにアクセスし、指示に従ってインストールする。\r\nデータベースはwp、サーバはlocalhostを入力してください。\r\n\r\n\r\n\r\n\r\n\r\n=========================================================\r\n以上でWordpressのインストールが完了です。\r\nプラグインなどまだいろいろできてないので、\r\nそれば別途記事していきます。</li>\r\n</ol>','WordPressの導入④　～WordPressをインストールする～','','inherit','closed','closed','','57-revision-v1','','','2017-12-14 23:59:36','2017-12-14 14:59:36','',57,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/57-revision-v1/',0,'revision','',0),(286,1,'2017-12-15 00:01:27','2017-12-14 15:01:27','①wp-config.phpを操作する\r\n<pre class=\"lang:sh decode:true \">$ vi /var/www/wordpress/wp-config.php</pre>\r\nへ\r\ndefine(\'FS_METHOD\',\'direct\');\r\nを追記\r\n\r\n②functions.phpにフィルターを追記する\r\n<pre class=\"lang:sh decode:true \">$ vi /var/www/wordpress/wp-includes/functions.php\r\n</pre>\r\nへ\r\nfunction set_fs_method($args) {\r\nreturn \'direct\';\r\n}\r\nadd_filter(\'filesystem_method\',\'set_fs_method\');\r\nを追記\r\n\r\n最後に追記すればOK。\r\n\r\nFTPの情報を入力しなくて更新できるようになる。','WordPressのバージョンアップでFTP情報を入力しないようにする','','inherit','closed','closed','','85-revision-v1','','','2017-12-15 00:01:27','2017-12-14 15:01:27','',85,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/85-revision-v1/',0,'revision','',0),(287,1,'2017-12-15 00:02:45','2017-12-14 15:02:45','デフォルトの投稿可能サイズは2MBです。\r\n・・えぇ、、小さすぎるでしょう・・。\r\n\r\niPhoneで投稿しようとしたら制限に引っかかったので、\r\n下記サイトを参考に変更しました。\r\nhttps://website-fun.com/upload-file-size/\r\n\r\n■PHP.iniで変更する\r\n\r\n最大メモリがすでに128MBだったので、こうした。\r\n<div class=\"line number1 index0 alt2\"><code class=\"xml plain\">memory_limit = 128M </code></div>\r\n<div class=\"line number2 index1 alt1\"><code class=\"xml plain\">post_max_size = 110M</code></div>\r\n<div class=\"line number3 index2 alt2\"><code class=\"xml plain\">upload_max_filesize = 100M</code></div>\r\n<div></div>\r\n<div>パースする最大時間とやらは、デフォルト60秒になってるぽかったので、</div>\r\n<div>\r\n\r\nいじらなかった。\r\n\r\nこれだけだと反映されなかったですが、\r\nApacheを再起動したら反映されました。\r\n<pre class=\"lang:sh decode:true \"># sudo service httpd restart</pre>\r\n&nbsp;\r\n\r\n</div>','WordPressで画像投稿サイズを変更','','inherit','closed','closed','','108-revision-v1','','','2017-12-15 00:02:45','2017-12-14 15:02:45','',108,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/108-revision-v1/',0,'revision','',0),(288,1,'2017-12-15 00:05:22','2017-12-14 15:05:22','<a href=\"http://www.tmotoki.net/category/wordpress/\">http://www.tmotoki.net/category/wordpress/</a>\r\n\r\n&nbsp;\r\n\r\n過去のWordpress関連記事を少しだけ修正しました。\r\nといってもコマンドがみにくいので、\r\n見やすく表示を変更しただけですが。\r\n\r\n過去の記事を見直すのも勉強になって良いなあと思いました。','過去の記事を修正','','publish','open','open','','%e9%81%8e%e5%8e%bb%e3%81%ae%e8%a8%98%e4%ba%8b%e3%82%92%e4%bf%ae%e6%ad%a3','','','2017-12-15 00:05:22','2017-12-14 15:05:22','',0,'http://www.tmotoki.net/?p=288',0,'post','',0),(289,1,'2017-12-15 00:05:22','2017-12-14 15:05:22','<a href=\"http://www.tmotoki.net/category/wordpress/\">http://www.tmotoki.net/category/wordpress/</a>\r\n\r\n&nbsp;\r\n\r\n過去のWordpress関連記事を少しだけ修正しました。\r\nといってもコマンドがみにくいので、\r\n見やすく表示を変更しただけですが。\r\n\r\n過去の記事を見直すのも勉強になって良いなあと思いました。','過去の記事を修正','','inherit','closed','closed','','288-revision-v1','','','2017-12-15 00:05:22','2017-12-14 15:05:22','',288,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/288-revision-v1/',0,'revision','',0),(290,1,'2017-12-15 00:06:54','2017-12-14 15:06:54','以前受けたセミナーで習ったこと。\r\n\r\n①パーマリンク設定\r\nカスタム構造に下記を入力\r\n/%category%/%postname%/\r\n\r\n→URLが分かりやすく短くなるよ。デフォルトだと長いですよ。\r\n\r\n②プラグイン設定\r\n設定\r\n・Hello Dollyを削除\r\n・Akismet有効化→APIキー登録\r\n・WP Multibyte Patchを有効化\r\n新規インストール\r\n・BackWPup(自動バックアップ)\r\n・Login rebuilder(管理画面ログインURL変更)\r\n・Show Current Template(どのテンプレートを使っているか表示)\r\n\r\n■APIキーの登録\r\nなんか手順違うかったけど一応のせとこう。\r\nhttps://whitehatseo.jp/setup-of-akismet/\r\nあなたが値段決めてね言われるので、0にする。\r\n（いやな顔をされる）\r\n\r\n■WP Multibyte Patchを利用するにはPHP の mbstring 関数が必要\r\n<pre class=\"lang:sh decode:true \">$ sudo yum -y install php-mbstring\r\n$ sudo service httpd restart</pre>\r\nインストールして、Apacheサーバを再起動して、はい終わり。\r\n\r\n新規追加は、新規追加ボタンを押して、\r\n検索ウィンドウで検索したら、出てくるのでインストールして有効化するだけ。\r\n\r\nShow Current Templateは何使ってるか見れるようになるので便利。\r\nバックアップはもしもの為ですね。\r\nログインURLの変更はセキュリティ対策です。\r\nURLを変えることによって、\r\nアタック回数が激減する（といいいな）と言われています。','WordPressで最初にすること','','inherit','closed','closed','','94-revision-v1','','','2017-12-15 00:06:54','2017-12-14 15:06:54','',94,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/94-revision-v1/',0,'revision','',0),(291,1,'2017-12-15 00:07:31','2017-12-14 15:07:31','デフォルトの投稿可能サイズは2MBです。\r\n・・えぇ、、小さすぎるでしょう・・。\r\n\r\niPhoneで投稿しようとしたら制限に引っかかったので、\r\n下記サイトを参考に変更しました。\r\nhttps://website-fun.com/upload-file-size/\r\n\r\n■PHP.iniで変更する\r\n\r\n最大メモリがすでに128MBだったので、こうした。\r\n<div class=\"line number1 index0 alt2\"><code class=\"xml plain\">memory_limit = 128M </code></div>\r\n<div class=\"line number2 index1 alt1\"><code class=\"xml plain\">post_max_size = 110M</code></div>\r\n<div class=\"line number3 index2 alt2\"><code class=\"xml plain\">upload_max_filesize = 100M</code></div>\r\n<div></div>\r\n<div>パースする最大時間とやらは、デフォルト60秒になってるぽかったので、</div>\r\n<div>\r\n\r\nいじらなかった。\r\n\r\nこれだけだと反映されなかったですが、\r\nApacheを再起動したら反映されました。\r\n<pre class=\"lang:sh decode:true \">$ sudo service httpd restart</pre>\r\n&nbsp;\r\n\r\n</div>','WordPressで画像投稿サイズを変更','','inherit','closed','closed','','108-revision-v1','','','2017-12-15 00:07:31','2017-12-14 15:07:31','',108,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/108-revision-v1/',0,'revision','',0),(292,1,'2017-12-15 00:08:52','2017-12-14 15:08:52','以前受けたセミナーで習ったこと。\r\n\r\n①パーマリンク設定\r\nカスタム構造に下記を入力\r\n/%category%/%postname%/\r\n\r\n→URLが分かりやすく短くなるよ。デフォルトだと長いですよ。\r\n\r\n②プラグイン設定\r\n-----設定\r\n・Hello Dollyを削除\r\n・Akismet有効化→APIキー登録\r\n・WP Multibyte Patchを有効化\r\n-----新規インストール\r\n・BackWPup(自動バックアップ)\r\n・Login rebuilder(管理画面ログインURL変更)\r\n・Show Current Template(どのテンプレートを使っているか表示)\r\n\r\n■APIキーの登録\r\nなんか手順違うかったけど一応のせとこう。\r\nhttps://whitehatseo.jp/setup-of-akismet/\r\nあなたが値段決めてね言われるので、0にする。\r\n（いやな顔をされる）\r\n\r\n■WP Multibyte Patchを利用するにはPHP の mbstring 関数が必要\r\n<pre class=\"lang:sh decode:true \">$ sudo yum -y install php-mbstring\r\n$ sudo service httpd restart</pre>\r\nインストールして、Apacheサーバを再起動して、はい終わり。\r\n\r\n新規追加は、新規追加ボタンを押して、\r\n検索ウィンドウで検索したら、出てくるのでインストールして有効化するだけ。\r\n\r\nShow Current Templateは何使ってるか見れるようになるので便利。\r\nバックアップはもしもの為ですね。\r\nログインURLの変更はセキュリティ対策です。\r\nURLを変えることによって、\r\nアタック回数が激減する（といいいな）と言われています。','WordPressで最初にすること','','inherit','closed','closed','','94-revision-v1','','','2017-12-15 00:08:52','2017-12-14 15:08:52','',94,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/94-revision-v1/',0,'revision','',0),(293,1,'2017-12-15 00:10:32','2017-12-14 15:10:32','使っているテーマが何故か公開日も表示しないので、\r\n自分で直接いじって表示しました。\r\n\r\nなんだかいろいろ記事がありましたが、\r\nどのファイルを編集するか、\r\n知ってる前提で書かれてる記事が多かったので、\r\n分からなかった点を記載してきます。\r\n\r\n■テーマ\r\n/(Wordpressの置き場所)/wp-content/themes/\r\n\r\nここにWordPressのテーマが入っています。\r\n目的のテーマがディレクトリになっているので、その中に入ります。\r\n\r\nトップページ→index.php\r\n投稿ページ→single.php\r\nサイドナビ→sidebar.php\r\nテーマ専用の機能→functions.php\r\n\r\n※WordPress全体用のfunctions.phpもあるので間違えないように注意が必要\r\n\r\n今回は投稿ページを直したいので、\r\nsingle.phpをテキストエディタで開きます。\r\n\r\nget_template_part(\'templates/content\' \'page\')\r\nというものが、ページがあるだけ読み込むという処理がありました。\r\nこれはなんですか？\r\n\r\nget_template_part()とは？\r\n好きなテンプレートを読み込む関数です。\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>引数名</th>\r\n<th>説明</th>\r\n<th>デフォルト</th>\r\n<th>必須</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>$slug</td>\r\n<td>テーマスラッグ名</td>\r\n<td>なし</td>\r\n<td>○</td>\r\n</tr>\r\n<tr>\r\n<td>$name</td>\r\n<td>特定テンプレート名</td>\r\n<td>なし</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\ncontentのpageというものを読み込んでいるらしい。\r\n合ってるかは知らないが、階層を調べていくと、\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/\r\nにある、\r\ncontent-page.php\r\nが怪しいと思われる。たぶん。\r\nちなみに\r\n(テーマ名)/templatesという中身には、\r\n本当のテンプレートがあったのでたぶんちがう。\r\n\r\nまずは公開日と更新日を返す関数をfunction.phpに追加しておきます。\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/function.php\r\nですよ。\r\n\r\n下記サイトを参考にしました。(というかそのまま頂きました・・）\r\n<a href=\"http://wispyon.com/published-modified-date/\">http://wispyon.com/published-modified-date/</a>\r\n<pre class=\"lang:php decode:true\">//更新日が投稿日より後なら返す\r\nfunction get_mtime($format) {\r\n    $mtime = get_the_modified_time(\'Ymd\');\r\n    $ptime = get_the_time(\'Ymd\');\r\n    if ($ptime &gt;= $mtime) {\r\n        return null;\r\n    } else {\r\n        return get_the_modified_time($format);\r\n    }\r\n}</pre>\r\n&lt;?php\r\nの後であればどこでもいいですが、\r\n可読性を考えて、function　～～ の並びにいれておきましょう。\r\n\r\nそして公開日時と更新日時を呼び出します。\r\n\r\n/(Wordpressの置き場所)/wp-content/themes/(テーマ名)/template-parts/content-page.php\r\nへ下記を追加します。\r\n<pre class=\"lang:xhtml decode:true \">&lt;div class=\"entry-date\"&gt;\r\n	&lt;?php if($mtime = get_mtime(\'Y.m.d\')) { ?&gt;\r\n		公開投稿日：\r\n		&lt;span itemprop=\"datePublished\" content=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" class=\"published\"&gt;\r\n		&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/span&gt;\r\n		最終更新日：\r\n		&lt;time itemprop=\"dateModified\" datetime=\"&lt;?php echo get_mtime(\'Y-m-d\') ?&gt;\" class=\"updated\"&gt;\r\n			&lt;?php echo $mtime ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } else { ?&gt;\r\n		公開日：\r\n		&lt;time itemprop=\"datePublished\" datetime=\"&lt;?php echo get_post_time(\'Y-m-d\') ?&gt;\" pubdate=\"pubdate\" class=\"published updated\"&gt;\r\n			&lt;?php echo get_post_time(\'Y.m.d\') ?&gt;\r\n		&lt;/time&gt;\r\n	&lt;?php } ?&gt;\r\n&lt;/div&gt;</pre>\r\n&nbsp;\r\n\r\nget_post_time(\'Y-m-d\') ・・・投稿日時を返す\r\nget_mtime(\'Y-m-d\')・・・さっき追加した公開日時を返す\r\n\r\nif文で更新日時が帰ってきたらどっちも表示して、\r\nなかったらnullなので公開日時だけ表示しますという感じです。\r\n\r\nそんでどこに追加したかというと、タイトルと記事の間、\r\nさらにヘッダーに含めたかったので、ここに入れました。\r\nテーマによって違うかもなので、参考程度に。\r\n<pre class=\"lang:xhtml decode:true \" title=\"挿入場所\">    &lt;header class=\"entry-header\"&gt;\r\n        &lt;?php     \r\n            if ( is_single() ) :\r\n            \r\n            the_title(\'&lt;h2 class=\"entry-title\"&gt;\', \'&lt;/h2&gt;\' );\r\n            \r\n            else:\r\n            \r\n            the_title( sprintf( \'&lt;h2 class=\"entry-title\"&gt;&lt;a href=\"%s\" rel=\"bookmark\"&gt;\', esc_url( get_permalink() ) ), \'&lt;/a&gt;&lt;/h2&gt;\' );\r\n            \r\n            endif; \r\n        ?&gt; \r\n\r\n&lt;!-- ★☆★☆★☆★☆★☆★☆★★☆★ --&gt;\r\n&lt;!-- ★☆★ここ！！！！！！！！★☆★ --&gt;\r\n&lt;!-- ★☆★☆★☆★☆★☆★☆★★☆★ --&gt;\r\n\r\n    &lt;/header&gt;&lt;!-- .entry-header --&gt;\r\n\r\n    &lt;div class=\"entry-content\"&gt;\r\n       &lt;?php \r\n			the_content( \r\n				sprintf( \r\n					__( \'Read More\', \'specia\' ), \r\n					\'&lt;span class=\"screen-reader-text\"&gt;  \'.get_the_title().\'&lt;/span&gt;\' \r\n				) \r\n			);\r\n		?&gt;\r\n    &lt;/div&gt;&lt;!-- .entry-content --&gt;</pre>\r\n&nbsp;\r\n\r\n<span class=\"crayon-r \">&lt;header </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-header\"</span><span class=\"crayon-r \">&gt;\r\n&lt;/header&gt;\r\n</span>の一番最後にいれました。\r\nその次のタグが\r\n<span class=\"crayon-r \">&lt;div </span><span class=\"crayon-e \">class</span><span class=\"crayon-o\">=</span><span class=\"crayon-s \">\"entry-content\"</span><span class=\"crayon-r \">&gt;</span>\r\nなので、記事の内容は始まってしまいますからね。\r\n\r\n&nbsp;\r\n\r\nわからないなりにいろいろ見てみましたが、\r\nPHPの使い方がおもしろいなあと思いました。\r\nファイルがきっとクラス的な意味合いを持ってるんだろうなあ。\r\n\r\n&nbsp;\r\n\r\nこれから勉強して使えるようになっていきたいと思います。\r\n\r\n&nbsp;\r\n\r\n■追記(2017.12.15)\r\n\r\n下記にも同じように挿入してやらないと、\r\n一部のページで日時が表示されませんでした。\r\n\r\ncontent.php\r\ncontent-search.php','WordPressに公開日と更新日を表示','','inherit','closed','closed','','185-revision-v1','','','2017-12-15 00:10:32','2017-12-14 15:10:32','',185,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/185-revision-v1/',0,'revision','',0),(294,1,'2017-12-15 00:35:12','2017-12-14 15:35:12','Node.jsでWebsocketを使ったチャットを昔作ったので、\r\nソースを置いておきます。\r\nといっても、オリジナルはログを残していくところだけですけど。\r\n\r\nメモ程度に～。\r\n自分でも忘れそうだったので。\r\n\r\n&nbsp;\r\n\r\nNode.jsではモジュールをhttp、socket.ioを使っています。\r\nWebサーバをhttpモジュールで立てて、\r\nsoket.ioでwebsocketをの処理を行っています。\r\n\r\nまたアクセスログを残したかったので、\r\nfsモジュールを使ってテキストファイルへIPと入力文字を保存しています。\r\n\r\nhtml側では画面表示はbootstrapを利用しており、\r\njavascriptでsocket.io.jsを使って、Websocketサーバにつないで、\r\nリアルタイムでやりとりできるようになっています。\r\n<pre class=\"lang:js decode:true\" title=\"Websocket兼Webサーバ\">var http = require( \'http\' ); // HTTPモジュール読み込み\r\nvar socketio = require( \'socket.io\' ); // Socket.IOモジュール読み込み\r\nvar fs = require( \'fs\' ); // ファイル入出力モジュール読み込み\r\n\r\n// 3000番ポートでHTTPサーバーを立てる\r\nvar server = http.createServer( function( req, res ) {\r\n    res.writeHead(200, { \'Content-Type\' : \'text/html\' }); // ヘッダ出力\r\n    res.end( fs.readFileSync(\'./index.html\', \'utf-8\') );  // index.htmlの内容を出力\r\n}).listen(3000);\r\n\r\n// サーバーをソケットに紐付ける\r\nvar io = socketio.listen( server );\r\n\r\n// 接続確立後の通信処理部分を定義\r\nio.sockets.on( \'connection\', function( socket ) {\r\n\r\n    // ip取得\r\n    var address = socket.handshake.address;\r\n    //console.log(address);\r\n    \r\n    // クライアントからサーバーへ メッセージ送信ハンドラ（自分を含む全員宛に送る）\r\n    socket.on( \'c2s_message\', function( data ) {\r\n    \r\n        // サーバーからクライアントへ メッセージを送り返し\r\n        io.sockets.emit( \'s2c_message\', { value : data.value } );\r\n        \r\n        // Log出力\r\n        var setLogText = (new Date()) + \", \" + address + \", \" + data.value + \"\\n\";\r\n        fs.appendFile(\'chat.log\', setLogText, function(err){\r\n           if( err != null ){\r\n                console.log(err);\r\n           }\r\n        });\r\n        \r\n    });\r\n\r\n    // クライアントからサーバーへ メッセージ送信ハンドラ（自分以外の全員宛に送る）\r\n    socket.on( \'c2s_broadcast\', function( data ) {\r\n        // サーバーからクライアントへ メッセージを送り返し\r\n        socket.broadcast.emit( \'s2c_message\', { value : data.value } );\r\n        \r\n        // Log出力\r\n        var setLogText = (new Date()) + \", \" + address + \", \" + data.value + \"\\n\";\r\n        fs.appendFile(\'chat.log\', setLogText, function(err){\r\n           if( err != null ){\r\n                console.log(err);\r\n           }\r\n        });\r\n\r\n    });\r\n});\r\n</pre>\r\n<pre class=\"lang:default decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html&gt;\r\n&lt;head&gt;\r\n    &lt;meta charset=\"UTF-8\"&gt;\r\n    &lt;link rel=\"stylesheet\" href=\"https://maxcdn.bootstrapcdn.com/bootstrap/3.3.5/css/bootstrap.min.css\"&gt;\r\n    &lt;style&gt;\r\n    #messageForm {\r\n        margin-top: 15px;\r\n    }\r\n    &lt;/style&gt;\r\n\r\n    &lt;script type=\"text/javascript\" src=\"https://ajax.googleapis.com/ajax/libs/jquery/1.5.1/jquery.min.js\"&gt;&lt;/script&gt;\r\n    &lt;script type=\"text/javascript\" src=\"/socket.io/socket.io.js\"&gt;&lt;/script&gt;\r\n&lt;/head&gt;\r\n&lt;body&gt;\r\n    &lt;div class=\"container\"&gt;\r\n        &lt;div class=\"row\"&gt;\r\n            &lt;div class=\"col-md-6 col-md-offset-3\"&gt;\r\n                &lt;form&gt;\r\n                    &lt;div class=\"form-group\"&gt;\r\n                        &lt;input type=\"text\" class=\"form-control\" id=\"messageForm\"&gt;\r\n                    &lt;/div&gt;\r\n                    &lt;div class=\"form-group\"&gt;\r\n                        &lt;button type=\"button\" class=\"btn btn-primary\" id=\"sendMessageBtn\"&gt;自分を含む全員に送信&lt;/button&gt;\r\n                        &lt;button type=\"button\" class=\"btn btn-primary\" id=\"sendMessageBroadcastBtn\"&gt;自分以外の全員に送信&lt;/button&gt;\r\n                    &lt;/div&gt;\r\n                &lt;/form&gt;\r\n                &lt;div id=\"messageView\"&gt;&lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n\r\n    &lt;script type=\"text/javascript\"&gt;\r\n    var ioSocket = io.connect( \"http://www.tmotoki.net:3000\" ); // チャットサーバーに接続\r\n\r\n    // サーバーからのデータ受け取り処理\r\n    ioSocket.on( \"connect\", function() {} ); // 接続\r\n    ioSocket.on( \"disconnect\", function() {} ); // 切断\r\n\r\n    // サーバーからクライアントへの送り返し\r\n    ioSocket.on( \"s2c_message\", function( data ) { appendMessage( data.value ) });\r\n\r\n    // 画面にメッセージを追記\r\n    function appendMessage( text ) {\r\n        $(\"#messageView\").append( \"&lt;div&gt;\" + text + \"&lt;/div&gt;\" );\r\n    }\r\n\r\n    // 自分を含む全員宛にメッセージを送信\r\n    $(\"#sendMessageBtn\").click( function() {\r\n\r\n        // メッセージの内容を取得し、その後フォームをクリア\r\n        var message = $(\"#messageForm\").val();\r\n        $(\"#messageForm\").val(\"\");\r\n\r\n        // クライアントからサーバーへ送信\r\n        ioSocket.emit( \"c2s_message\", { value : message } );\r\n    });\r\n\r\n    // 自分以外の全員宛にメッセージを送信\r\n    $(\"#sendMessageBroadcastBtn\").click( function() {\r\n\r\n        // メッセージの内容を取得し、その後フォームをクリア\r\n        var message = $(\"#messageForm\").val();\r\n        $(\"#messageForm\").val(\"\");\r\n\r\n        // クライアントからサーバーへ送信\r\n        ioSocket.emit( \"c2s_broadcast\", { value : message } );\r\n    });\r\n    &lt;/script&gt;\r\n&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','Websocketのチャット','','publish','open','open','','websocket%e3%81%ae%e3%83%81%e3%83%a3%e3%83%83%e3%83%88','','','2017-12-15 00:35:12','2017-12-14 15:35:12','',0,'http://www.tmotoki.net/?p=294',0,'post','',0),(295,1,'2017-12-15 00:35:12','2017-12-14 15:35:12','Node.jsでWebsocketを使ったチャットを昔作ったので、\r\nソースを置いておきます。\r\nといっても、オリジナルはログを残していくところだけですけど。\r\n\r\nメモ程度に～。\r\n自分でも忘れそうだったので。\r\n\r\n&nbsp;\r\n\r\nNode.jsではモジュールをhttp、socket.ioを使っています。\r\nWebサーバをhttpモジュールで立てて、\r\nsoket.ioでwebsocketをの処理を行っています。\r\n\r\nまたアクセスログを残したかったので、\r\nfsモジュールを使ってテキストファイルへIPと入力文字を保存しています。\r\n\r\nhtml側では画面表示はbootstrapを利用しており、\r\njavascriptでsocket.io.jsを使って、Websocketサーバにつないで、\r\nリアルタイムでやりとりできるようになっています。\r\n<pre class=\"lang:js decode:true\" title=\"Websocket兼Webサーバ\">var http = require( \'http\' ); // HTTPモジュール読み込み\r\nvar socketio = require( \'socket.io\' ); // Socket.IOモジュール読み込み\r\nvar fs = require( \'fs\' ); // ファイル入出力モジュール読み込み\r\n\r\n// 3000番ポートでHTTPサーバーを立てる\r\nvar server = http.createServer( function( req, res ) {\r\n    res.writeHead(200, { \'Content-Type\' : \'text/html\' }); // ヘッダ出力\r\n    res.end( fs.readFileSync(\'./index.html\', \'utf-8\') );  // index.htmlの内容を出力\r\n}).listen(3000);\r\n\r\n// サーバーをソケットに紐付ける\r\nvar io = socketio.listen( server );\r\n\r\n// 接続確立後の通信処理部分を定義\r\nio.sockets.on( \'connection\', function( socket ) {\r\n\r\n    // ip取得\r\n    var address = socket.handshake.address;\r\n    //console.log(address);\r\n    \r\n    // クライアントからサーバーへ メッセージ送信ハンドラ（自分を含む全員宛に送る）\r\n    socket.on( \'c2s_message\', function( data ) {\r\n    \r\n        // サーバーからクライアントへ メッセージを送り返し\r\n        io.sockets.emit( \'s2c_message\', { value : data.value } );\r\n        \r\n        // Log出力\r\n        var setLogText = (new Date()) + \", \" + address + \", \" + data.value + \"\\n\";\r\n        fs.appendFile(\'chat.log\', setLogText, function(err){\r\n           if( err != null ){\r\n                console.log(err);\r\n           }\r\n        });\r\n        \r\n    });\r\n\r\n    // クライアントからサーバーへ メッセージ送信ハンドラ（自分以外の全員宛に送る）\r\n    socket.on( \'c2s_broadcast\', function( data ) {\r\n        // サーバーからクライアントへ メッセージを送り返し\r\n        socket.broadcast.emit( \'s2c_message\', { value : data.value } );\r\n        \r\n        // Log出力\r\n        var setLogText = (new Date()) + \", \" + address + \", \" + data.value + \"\\n\";\r\n        fs.appendFile(\'chat.log\', setLogText, function(err){\r\n           if( err != null ){\r\n                console.log(err);\r\n           }\r\n        });\r\n\r\n    });\r\n});\r\n</pre>\r\n<pre class=\"lang:default decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html&gt;\r\n&lt;head&gt;\r\n    &lt;meta charset=\"UTF-8\"&gt;\r\n    &lt;link rel=\"stylesheet\" href=\"https://maxcdn.bootstrapcdn.com/bootstrap/3.3.5/css/bootstrap.min.css\"&gt;\r\n    &lt;style&gt;\r\n    #messageForm {\r\n        margin-top: 15px;\r\n    }\r\n    &lt;/style&gt;\r\n\r\n    &lt;script type=\"text/javascript\" src=\"https://ajax.googleapis.com/ajax/libs/jquery/1.5.1/jquery.min.js\"&gt;&lt;/script&gt;\r\n    &lt;script type=\"text/javascript\" src=\"/socket.io/socket.io.js\"&gt;&lt;/script&gt;\r\n&lt;/head&gt;\r\n&lt;body&gt;\r\n    &lt;div class=\"container\"&gt;\r\n        &lt;div class=\"row\"&gt;\r\n            &lt;div class=\"col-md-6 col-md-offset-3\"&gt;\r\n                &lt;form&gt;\r\n                    &lt;div class=\"form-group\"&gt;\r\n                        &lt;input type=\"text\" class=\"form-control\" id=\"messageForm\"&gt;\r\n                    &lt;/div&gt;\r\n                    &lt;div class=\"form-group\"&gt;\r\n                        &lt;button type=\"button\" class=\"btn btn-primary\" id=\"sendMessageBtn\"&gt;自分を含む全員に送信&lt;/button&gt;\r\n                        &lt;button type=\"button\" class=\"btn btn-primary\" id=\"sendMessageBroadcastBtn\"&gt;自分以外の全員に送信&lt;/button&gt;\r\n                    &lt;/div&gt;\r\n                &lt;/form&gt;\r\n                &lt;div id=\"messageView\"&gt;&lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n\r\n    &lt;script type=\"text/javascript\"&gt;\r\n    var ioSocket = io.connect( \"http://www.tmotoki.net:3000\" ); // チャットサーバーに接続\r\n\r\n    // サーバーからのデータ受け取り処理\r\n    ioSocket.on( \"connect\", function() {} ); // 接続\r\n    ioSocket.on( \"disconnect\", function() {} ); // 切断\r\n\r\n    // サーバーからクライアントへの送り返し\r\n    ioSocket.on( \"s2c_message\", function( data ) { appendMessage( data.value ) });\r\n\r\n    // 画面にメッセージを追記\r\n    function appendMessage( text ) {\r\n        $(\"#messageView\").append( \"&lt;div&gt;\" + text + \"&lt;/div&gt;\" );\r\n    }\r\n\r\n    // 自分を含む全員宛にメッセージを送信\r\n    $(\"#sendMessageBtn\").click( function() {\r\n\r\n        // メッセージの内容を取得し、その後フォームをクリア\r\n        var message = $(\"#messageForm\").val();\r\n        $(\"#messageForm\").val(\"\");\r\n\r\n        // クライアントからサーバーへ送信\r\n        ioSocket.emit( \"c2s_message\", { value : message } );\r\n    });\r\n\r\n    // 自分以外の全員宛にメッセージを送信\r\n    $(\"#sendMessageBroadcastBtn\").click( function() {\r\n\r\n        // メッセージの内容を取得し、その後フォームをクリア\r\n        var message = $(\"#messageForm\").val();\r\n        $(\"#messageForm\").val(\"\");\r\n\r\n        // クライアントからサーバーへ送信\r\n        ioSocket.emit( \"c2s_broadcast\", { value : message } );\r\n    });\r\n    &lt;/script&gt;\r\n&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','Websocketのチャット','','inherit','closed','closed','','294-revision-v1','','','2017-12-15 00:35:12','2017-12-14 15:35:12','',294,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/294-revision-v1/',0,'revision','',0),(296,1,'2017-12-15 22:44:29','2017-12-15 13:44:29','なんとなく敬遠してましたが、\r\n新しいものに手を出さないわけにもいかないので、\r\nATOMを使ってみようと思います。\r\n\r\n<a href=\"https://blog.codecamp.jp/atom_utility\">参考サイト</a>\r\n<ul>\r\n 	<li>タブ型で、使いやすいユーザーインターフェース</li>\r\n 	<li>無料で公開されているパッケージで機能追加が可能</li>\r\n 	<li>一つのウィンドウで単一のファイル、プロジェクト全体、複数のプロジェクトを開くことができる</li>\r\n</ul>\r\nですって。\r\n僕はLinuxとかも使うので、マルチプラットフォームところはGood。\r\n\r\nとりあえずインストール！\r\n\r\n<a href=\"https://atom.io/\">公式サイト</a>\r\n\r\n普通にDownload Windows 64bitでDLします。\r\nどうやらインストールはせずに、\r\n実行ファイルだけになりそうです。\r\nと思ったら違った。インストール速すぎて勘違いした。\r\n<h4>■日本語化</h4>\r\nメニューの　Settings\r\n＋Install\r\n\r\n「Japanese-menu」と入力して「Packages」ボタンを押すと\r\n検索結果が出てくるので、Installボタンを押す。\r\n\r\n&nbsp;\r\n<h4>■文字化け対策</h4>\r\nだいたいが文字コードがおかしい。\r\n環境設定で表示される「Settings」の画面で、「File Encoding」を変更\r\nUnicode(UTF-8）にしておきましょう。\r\nデフォルトでなってたよ。\r\n\r\n&nbsp;\r\n<h4>■便利なパッケージ</h4>\r\nパッケージ自体は、\r\n環境設定のパッケージ(Package)で、\r\n任意も文字を入れて検索して有効/無効を切り替えます。\r\n探すときは、日本語化と同じようにInstallから探します。\r\n<h5>autocomplete-plus</h5>\r\n予測変換を表示します。\r\nデフォルトでCSSやHTMLなどが有効になってるそうです。\r\n<h5 id=\"title1c084bc0d77254675e6535aca04c8657\">bracket-matcher</h5>\r\n対応する括弧を光らせたり、ジャンプしたりできます。\r\n\r\n&nbsp;\r\n<h5 id=\"titlea72ba64a5ef9b42a89e0d6a9f6cb2477\">Emmet</h5>\r\n主にHTMLやCSSの記述・編集をサポートするプラグインおよび省略記法です。\r\n予測変換ですね。\r\n\r\n&nbsp;\r\n<h5 id=\"title9603897fdcc4c0e352a6128e15833497\">minimap</h5>\r\n今作業しているエリアがコード全体のどこかを示すものです。\r\nコードが肥大化すると嬉しいですね。\r\n\r\n&nbsp;\r\n<h5>tag</h5>\r\n<code>&lt;/</code> まで入力すると自動で閉じタグを挿入。\r\n\r\n&nbsp;\r\n\r\nとりあえずこれだけ入れて、\r\n使って慣れろ！ってやつですね！','ATOM導入','','publish','open','open','','atom%e5%b0%8e%e5%85%a5','','','2017-12-15 23:48:23','2017-12-15 14:48:23','',0,'http://www.tmotoki.net/?p=296',0,'post','',1),(297,1,'2017-12-15 22:44:29','2017-12-15 13:44:29','なんとなく敬遠してましたが、\r\n新しいものに手を出さないわけにもいかないので、\r\nATOMを使ってみようと思います。\r\n\r\n<a href=\"https://blog.codecamp.jp/atom_utility\">参考サイト</a>\r\n<ul>\r\n 	<li>タブ型で、使いやすいユーザーインターフェース</li>\r\n 	<li>無料で公開されているパッケージで機能追加が可能</li>\r\n 	<li>一つのウィンドウで単一のファイル、プロジェクト全体、複数のプロジェクトを開くことができる</li>\r\n</ul>\r\nですって。\r\n僕はLinuxとかも使うので、マルチプラットフォームところはGood。\r\n\r\nとりあえずインストール！\r\n\r\n<a href=\"https://atom.io/\">公式サイト</a>\r\n\r\n普通にDownload Windows 64bitでDLします。\r\nどうやらインストールはせずに、\r\n実行ファイルだけになりそうです。\r\nと思ったら違った。インストール速すぎて勘違いした。\r\n<h4>\r\n■日本語化</h4>\r\nメニューの　Settings\r\n＋Install\r\n\r\n「Japanese-menu」と入力して「Packages」ボタンを押すと\r\n検索結果が出てくるので、Installボタンを押す。\r\n\r\n&nbsp;\r\n<h4>■文字化け対策</h4>\r\nだいたいが文字コードがおかしい。\r\n環境設定で表示される「Settings」の画面で、「File Encoding」を変更\r\nUnicode(UTF-8）にしておきましょう。\r\nデフォルトでなってたよ。\r\n\r\n&nbsp;\r\n<h4>■便利なパッケージ</h4>\r\nパッケージ自体は、\r\n環境設定のパッケージ(Package)で、\r\n任意も文字を入れて検索して有効/無効を切り替えます。\r\n探すときは、日本語化と同じようにInstallから探します。\r\n<h5>autocomplete-plus</h5>\r\n予測変換を表示します。\r\nデフォルトでCSSやHTMLなどが有効になってるそうです。\r\n<h5 id=\"title1c084bc0d77254675e6535aca04c8657\">bracket-matcher</h5>\r\n対応する括弧を光らせたり、ジャンプしたりできます。\r\n\r\n&nbsp;\r\n<h5 id=\"titlea72ba64a5ef9b42a89e0d6a9f6cb2477\">Emmet</h5>\r\n主にHTMLやCSSの記述・編集をサポートするプラグインおよび省略記法です。\r\n予測変換ですね。\r\n\r\n&nbsp;\r\n<h5 id=\"title9603897fdcc4c0e352a6128e15833497\">minimap</h5>\r\n今作業しているエリアがコード全体のどこかを示すものです。\r\nコードが肥大化すると嬉しいですね。\r\n\r\n&nbsp;\r\n\r\nとりあえずこれだけ入れて、\r\n使って慣れろ！ってやつですね！','ATOM導入','','inherit','closed','closed','','296-revision-v1','','','2017-12-15 22:44:29','2017-12-15 13:44:29','',296,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/296-revision-v1/',0,'revision','',0),(298,1,'2017-12-15 22:44:39','2017-12-15 13:44:39','なんとなく敬遠してましたが、\r\n新しいものに手を出さないわけにもいかないので、\r\nATOMを使ってみようと思います。\r\n\r\n<a href=\"https://blog.codecamp.jp/atom_utility\">参考サイト</a>\r\n<ul>\r\n 	<li>タブ型で、使いやすいユーザーインターフェース</li>\r\n 	<li>無料で公開されているパッケージで機能追加が可能</li>\r\n 	<li>一つのウィンドウで単一のファイル、プロジェクト全体、複数のプロジェクトを開くことができる</li>\r\n</ul>\r\nですって。\r\n僕はLinuxとかも使うので、マルチプラットフォームところはGood。\r\n\r\nとりあえずインストール！\r\n\r\n<a href=\"https://atom.io/\">公式サイト</a>\r\n\r\n普通にDownload Windows 64bitでDLします。\r\nどうやらインストールはせずに、\r\n実行ファイルだけになりそうです。\r\nと思ったら違った。インストール速すぎて勘違いした。\r\n<h4>■日本語化</h4>\r\nメニューの　Settings\r\n＋Install\r\n\r\n「Japanese-menu」と入力して「Packages」ボタンを押すと\r\n検索結果が出てくるので、Installボタンを押す。\r\n\r\n&nbsp;\r\n<h4>■文字化け対策</h4>\r\nだいたいが文字コードがおかしい。\r\n環境設定で表示される「Settings」の画面で、「File Encoding」を変更\r\nUnicode(UTF-8）にしておきましょう。\r\nデフォルトでなってたよ。\r\n\r\n&nbsp;\r\n<h4>■便利なパッケージ</h4>\r\nパッケージ自体は、\r\n環境設定のパッケージ(Package)で、\r\n任意も文字を入れて検索して有効/無効を切り替えます。\r\n探すときは、日本語化と同じようにInstallから探します。\r\n<h5>autocomplete-plus</h5>\r\n予測変換を表示します。\r\nデフォルトでCSSやHTMLなどが有効になってるそうです。\r\n<h5 id=\"title1c084bc0d77254675e6535aca04c8657\">bracket-matcher</h5>\r\n対応する括弧を光らせたり、ジャンプしたりできます。\r\n\r\n&nbsp;\r\n<h5 id=\"titlea72ba64a5ef9b42a89e0d6a9f6cb2477\">Emmet</h5>\r\n主にHTMLやCSSの記述・編集をサポートするプラグインおよび省略記法です。\r\n予測変換ですね。\r\n\r\n&nbsp;\r\n<h5 id=\"title9603897fdcc4c0e352a6128e15833497\">minimap</h5>\r\n今作業しているエリアがコード全体のどこかを示すものです。\r\nコードが肥大化すると嬉しいですね。\r\n\r\n&nbsp;\r\n\r\nとりあえずこれだけ入れて、\r\n使って慣れろ！ってやつですね！','ATOM導入','','inherit','closed','closed','','296-revision-v1','','','2017-12-15 22:44:39','2017-12-15 13:44:39','',296,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/296-revision-v1/',0,'revision','',0),(299,1,'2017-12-15 23:02:31','2017-12-15 14:02:31','<ul class=\"light-color-breadcrumb\">\r\n<ul class=\"light-color-breadcrumb\"></ul>\r\n</ul>\r\n<span style=\"color: #747474; font-family: \'Open Sans\', sans-serif; font-size: 14px;\">#07 擬似要素を使ってみよう</span>\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31707\">https://dotinstall.com/lessons/basic_css_v3/31707</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/07/\">http://www.tmotoki.net/static/dot_install/02_css/07/</a>\r\n\r\n■メモ\r\n疑似クラスと混同しがちだが、\r\n疑似クラスは「ある要素の状態を指定する」、\r\n疑似要素とは「ある要素の一部を指定する」ときに使う。\r\n\r\nなんのこっちゃわからん。\r\n\r\nおぉ。。\r\n1行目だけ色を変える指定、\r\np:first-lineしたら、動的に1行目だけ色が変わってる。\r\nすごいな。\r\n<pre class=\"lang:css decode:true\" title=\"css\">/*\r\n セレクタ\r\n 疑似要素\r\n*/\r\n\r\n/* p要素の最初の1行を色変える */\r\n/*p:first-line{color: skyblue;}*/\r\n\r\n/* p要素の最初の1文字色変える */\r\n/* p::first-letter{color: skyblue;} */\r\n\r\n/* 指定の要素の前と後ろに文字を追加 */\r\np::before{\r\n  content:\"--&gt;\";\r\n}\r\n\r\np::after{\r\n  content: \"&lt;--\"\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;p&gt;\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		&lt;/p&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #07(ドットインストール)','','publish','open','open','','css-07%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:45:43','2017-12-27 18:45:43','',0,'http://www.tmotoki.net/?p=299',0,'post','',0),(300,1,'2017-12-15 23:02:31','2017-12-15 14:02:31','<ul class=\"light-color-breadcrumb\">\r\n<ul class=\"light-color-breadcrumb\"></ul>\r\n</ul>\r\n<span style=\"color: #747474; font-family: \'Open Sans\', sans-serif; font-size: 14px;\">#07 擬似要素を使ってみよう</span>\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31707\">https://dotinstall.com/lessons/basic_css_v3/31707</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/07/\">http://www.tmotoki.net/static/dot_install/02_css/07/</a>\r\n\r\n■メモ\r\n疑似クラスと混同しがちだが、\r\n疑似クラスは「ある要素の状態を指定する」、\r\n疑似要素とは「ある要素の一部を指定する」ときに使う。\r\n\r\nなんのこっちゃわからん。\r\n\r\nおぉ。。\r\n1行目だけ色を変える指定、\r\np:first-lineしたら、動的に1行目だけ色が変わってる。\r\nすごいな。\r\n<pre class=\"lang:css decode:true\" title=\"css\">/*\r\n セレクタ\r\n 疑似要素\r\n*/\r\n\r\n/* p要素の最初の1行を色変える */\r\n/*p:first-line{color: skyblue;}*/\r\n\r\n/* p要素の最初の1文字色変える */\r\n/* p::first-letter{color: skyblue;} */\r\n\r\n/* 指定の要素の前と後ろに文字を追加 */\r\np::before{\r\n  content:\"--&gt;\";\r\n}\r\n\r\np::after{\r\n  content: \"&lt;--\"\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;p&gt;\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		こんにちは。こんにちは。こんにちは。\r\n		&lt;/p&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #07(ドットインストール)','','inherit','closed','closed','','299-revision-v1','','','2017-12-15 23:02:31','2017-12-15 14:02:31','',299,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/299-revision-v1/',0,'revision','',0),(301,1,'2017-12-15 23:20:35','2017-12-15 14:20:35','#08 セレクタの詳細度を理解しよう\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31708\">https://dotinstall.com/lessons/basic_css_v3/31708</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/08/\">http://www.tmotoki.net/static/dot_install/02_css/08/</a>\r\n\r\n■メモ\r\n\r\n(a) style=\"\"\r\n(b) id\r\n(c) 属性/疑似クラス\r\n(d) 要素/疑似要素\r\n\r\n(a)～(d)の4つに対して点がふられて、\r\n(a)←(b)←(c)←(d)の順に優先される。\r\n\r\nたとえばbに1点もってたら、\r\ncとdにいくつ点があってもbが優先される。\r\n※たぶん・・。検証した感じそんな感じでした。\r\n\r\n優先度も点数も同じ場合、\r\nあとに書いたものが優先される。\r\n\r\n!importantをつけると、全部無視して最優先になる。\r\n乱用してはわけがわからなくなるのでダメ。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n セレクタ\r\n 詳細度\r\n   (a) style=\"\"\r\n   (b) id\r\n   (c) 属性/疑似クラス\r\n   (d) 要素/疑似要素\r\n*/\r\n\r\n/* (a)0, (b)0, (c)0, (d)1 */\r\na{color: skyblue;}\r\n\r\n/* (a)0, (b)0, (c)1, (d)1 */\r\na.link{color: pink !important;}\r\n\r\n/* (a)0, (b)1, (c)0, (d)1 */\r\na#site{color: blue;}\r\n\r\n/* (a)0, (b)0, (c)1, (d)1 */\r\na.search{color: orange;}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;a href=\"http://dotinstall.com\" class=\"link search\" id=\"site\"&gt;\r\n			dotinstall\r\n		&lt;/a&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #08(ドットインストール)','','publish','open','open','','css-08%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:45:43','2017-12-27 18:45:43','',0,'http://www.tmotoki.net/?p=301',0,'post','',0),(302,1,'2017-12-15 23:20:35','2017-12-15 14:20:35','#08 セレクタの詳細度を理解しよう\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31708\">https://dotinstall.com/lessons/basic_css_v3/31708</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/08/\">http://www.tmotoki.net/static/dot_install/02_css/08/</a>\r\n\r\n■メモ\r\n\r\n(a) style=\"\"\r\n(b) id\r\n(c) 属性/疑似クラス\r\n(d) 要素/疑似要素\r\n\r\n(a)～(d)の4つに対して1点ずつふられて、\r\n最も点数の高い設定が優先される。\r\n\r\n同じ点数だと、(a)←(b)←(c)←(d)の順で、\r\n点数の持っているものが優先さえれる。\r\n\r\n優先度も点数も同じ場合、\r\nあとに書いたものが優先される。\r\n\r\n!importantをつけると、全部無視して最優先になる。\r\n乱用してはわけがわからなくなるのでダメ。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n セレクタ\r\n 詳細度\r\n   (a) style=\"\"\r\n   (b) id\r\n   (c) 属性/疑似クラス\r\n   (d) 要素/疑似要素\r\n*/\r\n\r\n/* (a)0, (b)0, (c)0, (d)1 */\r\na{color: skyblue;}\r\n\r\n/* (a)0, (b)0, (c)1, (d)1 */\r\na.link{color: pink !important;}\r\n\r\n/* (a)0, (b)1, (c)0, (d)1 */\r\na#site{color: blue;}\r\n\r\n/* (a)0, (b)0, (c)1, (d)1 */\r\na.search{color: orange;}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;a href=\"http://dotinstall.com\" class=\"link search\" id=\"site\"&gt;\r\n			dotinstall\r\n		&lt;/a&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #08(ドットインストール)','','inherit','closed','closed','','301-revision-v1','','','2017-12-15 23:20:35','2017-12-15 14:20:35','',301,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/301-revision-v1/',0,'revision','',0),(303,1,'2017-12-16 00:17:45','2017-12-15 15:17:45','<h4>#09 プロパティの値を指定しよう</h4>\r\n<h5>■動画</h5>\r\nhttps://dotinstall.com/lessons/basic_css_v3/31709\r\n<h5>■作成物</h5>\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/09/\">http://www.tmotoki.net/static/dot_install/02_css/09/</a>\r\n<h5>■メモ</h5>\r\nプロパティの値の指定方法\r\n- 長さ\r\n- px ピクセル(ドットの数)\r\n- em 相対的な大きさ(倍率)\r\n- % ベースの何％か\r\n- 色\r\n- 色の名前\r\n- RGB(#000000～#FFFFFF) 24bit\r\n- Red(#FF0000)\r\n- Grean(#00FF00)\r\n- Blue(#0000FF)\r\n※数値や%で示すことができる\r\n16進数 00-ff(0-f)\r\n10進数 0-255\r\n％ 0%-100%\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n プロパティの値の指定方法\r\n*/\r\n\r\n/* 長さ */\r\nbody{ font-size: 16px;}\r\nh1 { font-size: 2em;} /* 32px */\r\nh2 { font-size: 150%;} /* 24px */\r\n\r\n/* ぜんぶ青 */\r\nh1 { color: blue;}\r\nh1 { color: #00f;}\r\nh1 { color: #0000ff;}\r\nh1 { color: rgb(0, 0, 255);}\r\nh1 { color: rgb(0%, 0%, 100%);}\r\n\r\n/* rgbaもできるらしい。h3を透けさせてみる */\r\n/* 透明度は小数で指定しないといけないらしい */\r\nh3 { color: rgba(0, 0, 0, 0.5);}\r\nh4 { color: rgba(100%, 0%, 0%, 0.25);}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;h1&gt;title&lt;/h1&gt;\r\n		&lt;h2&gt;sub title&lt;/h2&gt;\r\n		&lt;h3&gt;すけますかな？&lt;/h3&gt;\r\n		&lt;h4&gt;これはどーかな？&lt;/h4&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;</pre>\r\n&nbsp;','CSS #09(ドットインストール)','','publish','open','open','','css-09%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:45:43','2017-12-27 18:45:43','',0,'http://www.tmotoki.net/?p=303',0,'post','',0),(304,1,'2017-12-15 23:47:49','2017-12-15 14:47:49','なんとなく敬遠してましたが、\n新しいものに手を出さないわけにもいかないので、\nATOMを使ってみようと思います。\n\n<a href=\"https://blog.codecamp.jp/atom_utility\">参考サイト</a>\n<ul>\n 	<li>タブ型で、使いやすいユーザーインターフェース</li>\n 	<li>無料で公開されているパッケージで機能追加が可能</li>\n 	<li>一つのウィンドウで単一のファイル、プロジェクト全体、複数のプロジェクトを開くことができる</li>\n</ul>\nですって。\n僕はLinuxとかも使うので、マルチプラットフォームところはGood。\n\nとりあえずインストール！\n\n<a href=\"https://atom.io/\">公式サイト</a>\n\n普通にDownload Windows 64bitでDLします。\nどうやらインストールはせずに、\n実行ファイルだけになりそうです。\nと思ったら違った。インストール速すぎて勘違いした。\n<h4>■日本語化</h4>\nメニューの　Settings\n＋Install\n\n「Japanese-menu」と入力して「Packages」ボタンを押すと\n検索結果が出てくるので、Installボタンを押す。\n\n&nbsp;\n<h4>■文字化け対策</h4>\nだいたいが文字コードがおかしい。\n環境設定で表示される「Settings」の画面で、「File Encoding」を変更\nUnicode(UTF-8）にしておきましょう。\nデフォルトでなってたよ。\n\n&nbsp;\n<h4>■便利なパッケージ</h4>\nパッケージ自体は、\n環境設定のパッケージ(Package)で、\n任意も文字を入れて検索して有効/無効を切り替えます。\n探すときは、日本語化と同じようにInstallから探します。\n<h5>autocomplete-plus</h5>\n予測変換を表示します。\nデフォルトでCSSやHTMLなどが有効になってるそうです。\n<h5 id=\"title1c084bc0d77254675e6535aca04c8657\">bracket-matcher</h5>\n対応する括弧を光らせたり、ジャンプしたりできます。\n\n&nbsp;\n<h5 id=\"titlea72ba64a5ef9b42a89e0d6a9f6cb2477\">Emmet</h5>\n主にHTMLやCSSの記述・編集をサポートするプラグインおよび省略記法です。\n予測変換ですね。\n\n&nbsp;\n<h5 id=\"title9603897fdcc4c0e352a6128e15833497\">minimap</h5>\n今作業しているエリアがコード全体のどこかを示すものです。\nコードが肥大化すると嬉しいですね。\n<h5>tag</h5>\n<code>&lt;/</code> まで入力すると自動で閉じタグを挿入。\n\n&nbsp;\n\nとりあえずこれだけ入れて、\n使って慣れろ！ってやつですね！','ATOM導入','','inherit','closed','closed','','296-autosave-v1','','','2017-12-15 23:47:49','2017-12-15 14:47:49','',296,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/296-autosave-v1/',0,'revision','',0),(305,1,'2017-12-15 23:48:23','2017-12-15 14:48:23','なんとなく敬遠してましたが、\r\n新しいものに手を出さないわけにもいかないので、\r\nATOMを使ってみようと思います。\r\n\r\n<a href=\"https://blog.codecamp.jp/atom_utility\">参考サイト</a>\r\n<ul>\r\n 	<li>タブ型で、使いやすいユーザーインターフェース</li>\r\n 	<li>無料で公開されているパッケージで機能追加が可能</li>\r\n 	<li>一つのウィンドウで単一のファイル、プロジェクト全体、複数のプロジェクトを開くことができる</li>\r\n</ul>\r\nですって。\r\n僕はLinuxとかも使うので、マルチプラットフォームところはGood。\r\n\r\nとりあえずインストール！\r\n\r\n<a href=\"https://atom.io/\">公式サイト</a>\r\n\r\n普通にDownload Windows 64bitでDLします。\r\nどうやらインストールはせずに、\r\n実行ファイルだけになりそうです。\r\nと思ったら違った。インストール速すぎて勘違いした。\r\n<h4>■日本語化</h4>\r\nメニューの　Settings\r\n＋Install\r\n\r\n「Japanese-menu」と入力して「Packages」ボタンを押すと\r\n検索結果が出てくるので、Installボタンを押す。\r\n\r\n&nbsp;\r\n<h4>■文字化け対策</h4>\r\nだいたいが文字コードがおかしい。\r\n環境設定で表示される「Settings」の画面で、「File Encoding」を変更\r\nUnicode(UTF-8）にしておきましょう。\r\nデフォルトでなってたよ。\r\n\r\n&nbsp;\r\n<h4>■便利なパッケージ</h4>\r\nパッケージ自体は、\r\n環境設定のパッケージ(Package)で、\r\n任意も文字を入れて検索して有効/無効を切り替えます。\r\n探すときは、日本語化と同じようにInstallから探します。\r\n<h5>autocomplete-plus</h5>\r\n予測変換を表示します。\r\nデフォルトでCSSやHTMLなどが有効になってるそうです。\r\n<h5 id=\"title1c084bc0d77254675e6535aca04c8657\">bracket-matcher</h5>\r\n対応する括弧を光らせたり、ジャンプしたりできます。\r\n\r\n&nbsp;\r\n<h5 id=\"titlea72ba64a5ef9b42a89e0d6a9f6cb2477\">Emmet</h5>\r\n主にHTMLやCSSの記述・編集をサポートするプラグインおよび省略記法です。\r\n予測変換ですね。\r\n\r\n&nbsp;\r\n<h5 id=\"title9603897fdcc4c0e352a6128e15833497\">minimap</h5>\r\n今作業しているエリアがコード全体のどこかを示すものです。\r\nコードが肥大化すると嬉しいですね。\r\n\r\n&nbsp;\r\n<h5>tag</h5>\r\n<code>&lt;/</code> まで入力すると自動で閉じタグを挿入。\r\n\r\n&nbsp;\r\n\r\nとりあえずこれだけ入れて、\r\n使って慣れろ！ってやつですね！','ATOM導入','','inherit','closed','closed','','296-revision-v1','','','2017-12-15 23:48:23','2017-12-15 14:48:23','',296,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/296-revision-v1/',0,'revision','',0),(306,1,'2017-12-16 00:17:45','2017-12-15 15:17:45','<h4>#09 プロパティの値を指定しよう</h4>\r\n<h5>■動画</h5>\r\nhttps://dotinstall.com/lessons/basic_css_v3/31709\r\n<h5>■作成物</h5>\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/09/\">http://www.tmotoki.net/static/dot_install/02_css/09/</a>\r\n<h5>■メモ</h5>\r\nプロパティの値の指定方法\r\n- 長さ\r\n- px ピクセル(ドットの数)\r\n- em 相対的な大きさ(倍率)\r\n- % ベースの何％か\r\n- 色\r\n- 色の名前\r\n- RGB(#000000～#FFFFFF) 24bit\r\n- Red(#FF0000)\r\n- Grean(#00FF00)\r\n- Blue(#0000FF)\r\n※数値や%で示すことができる\r\n16進数 00-ff(0-f)\r\n10進数 0-255\r\n％ 0%-100%\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n プロパティの値の指定方法\r\n*/\r\n\r\n/* 長さ */\r\nbody{ font-size: 16px;}\r\nh1 { font-size: 2em;} /* 32px */\r\nh2 { font-size: 150%;} /* 24px */\r\n\r\n/* ぜんぶ青 */\r\nh1 { color: blue;}\r\nh1 { color: #00f;}\r\nh1 { color: #0000ff;}\r\nh1 { color: rgb(0, 0, 255);}\r\nh1 { color: rgb(0%, 0%, 100%);}\r\n\r\n/* rgbaもできるらしい。h3を透けさせてみる */\r\n/* 透明度は小数で指定しないといけないらしい */\r\nh3 { color: rgba(0, 0, 0, 0.5);}\r\nh4 { color: rgba(100%, 0%, 0%, 0.25);}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;h1&gt;title&lt;/h1&gt;\r\n		&lt;h2&gt;sub title&lt;/h2&gt;\r\n		&lt;h3&gt;すけますかな？&lt;/h3&gt;\r\n		&lt;h4&gt;これはどーかな？&lt;/h4&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;</pre>\r\n&nbsp;','CSS #09(ドットインストール)','','inherit','closed','closed','','303-revision-v1','','','2017-12-16 00:17:45','2017-12-15 15:17:45','',303,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/303-revision-v1/',0,'revision','',0),(308,1,'2017-12-16 00:36:13','2017-12-15 15:36:13','#08 セレクタの詳細度を理解しよう\n\n■動画\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31708\">https://dotinstall.com/lessons/basic_css_v3/31708</a>\n\n■作成物\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/08/\">http://www.tmotoki.net/static/dot_install/02_css/08/</a>\n\n■メモ\n\n(a) style=\"\"\n(b) id\n(c) 属性/疑似クラス\n(d) 要素/疑似要素\n\n(a)～(d)の4つに対して点がふられて、\n(a)←(b)←(c)←(d)の順に優先される。\n\nたとえばbに1点もってたら、\ncとdにいくつ点があってもbが優先される。\n※たぶん・・。検証した感じそんな感じでした。\n\nその合計最も点数の高い設定が優先される。\n\n同じ点数だと、の順で、\n点数の持っているものが優先される。\nうーん、点数\n\n優先度も点数も同じ場合、\nあとに書いたものが優先される。\n\n!importantをつけると、全部無視して最優先になる。\n乱用してはわけがわからなくなるのでダメ。\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\n セレクタ\n 詳細度\n   (a) style=\"\"\n   (b) id\n   (c) 属性/疑似クラス\n   (d) 要素/疑似要素\n*/\n\n/* (a)0, (b)0, (c)0, (d)1 */\na{color: skyblue;}\n\n/* (a)0, (b)0, (c)1, (d)1 */\na.link{color: pink !important;}\n\n/* (a)0, (b)1, (c)0, (d)1 */\na#site{color: blue;}\n\n/* (a)0, (b)0, (c)1, (d)1 */\na.search{color: orange;}</pre>\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\n&lt;html lang=\"ja\"&gt;\n	&lt;head&gt;\n		&lt;meta charset=\"utf8\"&gt;\n		&lt;title&gt;CSS Practice&lt;/title&gt;\n	&lt;/head&gt;\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\n	&lt;body&gt;\n		&lt;a href=\"http://dotinstall.com\" class=\"link search\" id=\"site\"&gt;\n			dotinstall\n		&lt;/a&gt;\n	&lt;/body&gt;\n&lt;/html&gt;\n</pre>\n&nbsp;','CSS #08(ドットインストール)','','inherit','closed','closed','','301-autosave-v1','','','2017-12-16 00:36:13','2017-12-15 15:36:13','',301,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/301-autosave-v1/',0,'revision','',0),(309,1,'2017-12-16 00:36:37','2017-12-15 15:36:37','#08 セレクタの詳細度を理解しよう\r\n\r\n■動画\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31708\">https://dotinstall.com/lessons/basic_css_v3/31708</a>\r\n\r\n■作成物\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/08/\">http://www.tmotoki.net/static/dot_install/02_css/08/</a>\r\n\r\n■メモ\r\n\r\n(a) style=\"\"\r\n(b) id\r\n(c) 属性/疑似クラス\r\n(d) 要素/疑似要素\r\n\r\n(a)～(d)の4つに対して点がふられて、\r\n(a)←(b)←(c)←(d)の順に優先される。\r\n\r\nたとえばbに1点もってたら、\r\ncとdにいくつ点があってもbが優先される。\r\n※たぶん・・。検証した感じそんな感じでした。\r\n\r\n優先度も点数も同じ場合、\r\nあとに書いたものが優先される。\r\n\r\n!importantをつけると、全部無視して最優先になる。\r\n乱用してはわけがわからなくなるのでダメ。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n セレクタ\r\n 詳細度\r\n   (a) style=\"\"\r\n   (b) id\r\n   (c) 属性/疑似クラス\r\n   (d) 要素/疑似要素\r\n*/\r\n\r\n/* (a)0, (b)0, (c)0, (d)1 */\r\na{color: skyblue;}\r\n\r\n/* (a)0, (b)0, (c)1, (d)1 */\r\na.link{color: pink !important;}\r\n\r\n/* (a)0, (b)1, (c)0, (d)1 */\r\na#site{color: blue;}\r\n\r\n/* (a)0, (b)0, (c)1, (d)1 */\r\na.search{color: orange;}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;a href=\"http://dotinstall.com\" class=\"link search\" id=\"site\"&gt;\r\n			dotinstall\r\n		&lt;/a&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #08(ドットインストール)','','inherit','closed','closed','','301-revision-v1','','','2017-12-16 00:36:37','2017-12-15 15:36:37','',301,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/301-revision-v1/',0,'revision','',0),(311,1,'2017-12-16 01:00:28','2017-12-15 16:00:28','<h4>#10 ボックスモデルを理解しよう</h4>\r\n<h5>\r\n■動画</h5>\r\nhttps://dotinstall.com/lessons/basic_css_v3/31710\r\n<h5>■作成物</h5>\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/10/\">http://www.tmotoki.net/static/dot_install/02_css/10/</a>\r\n<h5>■メモ</h5>\r\n<img class=\"alignnone size-full wp-image-312\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/12/10.png\" alt=\"\" width=\"275\" height=\"190\" />\r\n\r\n&nbsp;\r\n\r\nこれはたしかWebデザイナーのベーシックにでてきた。\r\nなんだか覚えにくいけど・・。\r\n\r\n基本divタグで区切っていくんですよね。\r\n\r\n余白は重要です。\r\n20年前に初めてWebページを自作したときから、\r\n社会人になってからもそれは感じます。\r\n\r\nwidthを%で指定すると、\r\nWindowの大きさにあわせて変わってくれます。\r\nおぉ。レスポンシブデザイン(笑)\r\n\r\nheightは％で指定するとクセがあります。\r\n親要素の高さを明示的に示してあげないと、\r\nただしく動作しません。\r\n\r\nこの例だとdivの親がbodyとhtmlなので、\r\n両方のタグに100%と設定するか、\r\n親に100pxなど直接指定してあげないといけません。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n ボックスモデル\r\n */\r\n\r\nbody, html{\r\n  height: 100%;\r\n}\r\n\r\ndiv {\r\n  background: silver;\r\n  /* width: 200px; */\r\n  width: 50%;\r\n  /* height: 100px; */\r\n  height: 50%;\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;div&gt;Element&lt;/div&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #10(ドットインストール)','','publish','open','open','','css-10%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:45:43','2017-12-27 18:45:43','',0,'http://www.tmotoki.net/?p=311',0,'post','',0),(312,1,'2017-12-16 00:46:20','2017-12-15 15:46:20','','10','','inherit','open','closed','','10','','','2017-12-16 00:46:20','2017-12-15 15:46:20','',311,'http://www.tmotoki.net/wp-content/uploads/2017/12/10.png',0,'attachment','image/png',0),(313,1,'2017-12-16 01:00:28','2017-12-15 16:00:28','<h4>#10 ボックスモデルを理解しよう</h4>\r\n<h5>\r\n■動画</h5>\r\nhttps://dotinstall.com/lessons/basic_css_v3/31710\r\n<h5>■作成物</h5>\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/10/\">http://www.tmotoki.net/static/dot_install/02_css/10/</a>\r\n<h5>■メモ</h5>\r\n<img class=\"alignnone size-full wp-image-312\" src=\"http://www.tmotoki.net/wp-content/uploads/2017/12/10.png\" alt=\"\" width=\"275\" height=\"190\" />\r\n\r\n&nbsp;\r\n\r\nこれはたしかWebデザイナーのベーシックにでてきた。\r\nなんだか覚えにくいけど・・。\r\n\r\n基本divタグで区切っていくんですよね。\r\n\r\n余白は重要です。\r\n20年前に初めてWebページを自作したときから、\r\n社会人になってからもそれは感じます。\r\n\r\nwidthを%で指定すると、\r\nWindowの大きさにあわせて変わってくれます。\r\nおぉ。レスポンシブデザイン(笑)\r\n\r\nheightは％で指定するとクセがあります。\r\n親要素の高さを明示的に示してあげないと、\r\nただしく動作しません。\r\n\r\nこの例だとdivの親がbodyとhtmlなので、\r\n両方のタグに100%と設定するか、\r\n親に100pxなど直接指定してあげないといけません。\r\n<pre class=\"lang:css decode:true \" title=\"CSS\">/*\r\n ボックスモデル\r\n */\r\n\r\nbody, html{\r\n  height: 100%;\r\n}\r\n\r\ndiv {\r\n  background: silver;\r\n  /* width: 200px; */\r\n  width: 50%;\r\n  /* height: 100px; */\r\n  height: 50%;\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;div&gt;Element&lt;/div&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #10(ドットインストール)','','inherit','closed','closed','','311-revision-v1','','','2017-12-16 01:00:28','2017-12-15 16:00:28','',311,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/311-revision-v1/',0,'revision','',0),(314,1,'2017-12-16 08:21:14','2017-12-15 23:21:14','すごい快適でした（笑）\r\n\r\nコーディング速度が普通のテキストエディタの、1.5倍(当社比?)\r\n\r\n&nbsp;\r\n\r\nこの軽さでこの高機能は、流行ってるの納得です。\r\n\r\nビルドがある言語だとしんどいけど、スクリプト言語ならこれ一択でいいです。個人的に。\r\n\r\n&nbsp;\r\n\r\nあとは変数名一括リネームとか、関数に飛ぶとかができるのになればIDEいらないかも、、？\r\n\r\nインテリセンスある時点で結構衝撃的でした。探してたので。\r\n\r\n&nbsp;\r\n\r\nまあ無料でここまで高機能だと仕事でも使いやすいので、もっといろいろ出来ないか調べてみます。','ATOMでちょっとやってみて','','publish','open','open','','atom%e3%81%a7%e3%81%a1%e3%82%87%e3%81%a3%e3%81%a8%e3%82%84%e3%81%a3%e3%81%a6%e3%81%bf%e3%81%a6','','','2017-12-16 08:21:14','2017-12-15 23:21:14','',0,'http://www.tmotoki.net/?p=314',0,'post','',0),(315,1,'2017-12-16 08:20:58','2017-12-15 23:20:58','すごい快適でした（笑）\r\n\r\nコーディング速度が普通のテキストエディタの、1.5倍(当社比?)\r\n\r\n&nbsp;\r\n\r\nこの軽さでこの高機能は、流行ってるの納得です。\r\n\r\nビルドがある言語だとしんどいけど、スクリプト言語ならこれ一択でいいです。個人的に。\r\n\r\n&nbsp;\r\n\r\nあとは変数名一括リネームとか、関数に飛ぶとかができるのになればIDEいらないかも、、？\r\n\r\nインテリセンスある時点で結構衝撃的でした。探してたので。\r\n\r\n&nbsp;\r\n\r\nまあ無料でここまで高機能だと仕事でも使いやすいので、もっといろいろ出来ないか調べてみます。','ATOMでちょっとやってみて','','inherit','closed','closed','','314-revision-v1','','','2017-12-16 08:20:58','2017-12-15 23:20:58','',314,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/314-revision-v1/',0,'revision','',0),(316,1,'2017-12-17 22:59:36','2017-12-17 13:59:36','<h4>#11 borderで境界線のスタイルを変えよう</h4>\r\n<h5>■動画</h5>\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31711\">https://dotinstall.com/lessons/basic_css_v3/31711</a>\r\n\r\n&nbsp;\r\n<h5>■作成物</h5>\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/11/\">http://www.tmotoki.net/static/dot_install/02_css/11/</a>\r\n\r\n&nbsp;\r\n<h5>■メモ</h5>\r\nborderで枠を作り、デザインすることができる。\r\n色、幅、スタイルでデザインできる。\r\n個別に項目で指定もできるが、まとめることもできる。\r\n\r\nまとめる場合は、\r\nborder: orange, 4px dotted\r\nのように、borderにスペースで区切って、\r\ncolor width styleの順に指定する。\r\n\r\n右だけ、左だけの枠のみ変更するといった指定ものできる。\r\nborder-top\r\nborder-bottom\r\nborder-right\r\nborder-left\r\n<pre class=\"lang:css decode:true \" title=\"css\">/*\r\n boder\r\n  boder-color:枠の色\r\n  boder-width:枠の幅(太さのイメージ)\r\n  boder-style:種類\r\n    solid:実線\r\n    botted:点線\r\n    dashed:破線\r\n    double:二重線\r\n    inset:立体的に見せる\r\n    outset:同上(あんまり違いが分からん)\r\n */\r\n\r\ndiv {\r\n  /* 個別指定した場合 */\r\n  /* border-color: orange;\r\n  border-width: 4px;\r\n  border-style: double; */\r\n\r\n  /* まとめた場合 */\r\n  /* border: orange 4px dotted; */\r\n\r\n  /* それぞれの枠に設定する */\r\n  border-top: orange 1px solid;\r\n  border-bottom: pink 2px dotted;\r\n  border-right: blue 8px inset;\r\n  border-left: violet 8px outset;\r\n\r\n  /* ちょっとわかりにくいので枠の幅を半分に */\r\n  width: 50%;\r\n\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;div&gt;Element&lt;/div&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #11(ドットインストール)','','publish','open','open','','css-11%e3%83%89%e3%83%83%e3%83%88%e3%82%a4%e3%83%b3%e3%82%b9%e3%83%88%e3%83%bc%e3%83%ab','','','2017-12-28 03:45:43','2017-12-27 18:45:43','',0,'http://www.tmotoki.net/?p=316',0,'post','',0),(317,1,'2017-12-17 22:59:36','2017-12-17 13:59:36','<h4>#11 borderで境界線のスタイルを変えよう</h4>\r\n<h5>■動画</h5>\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31711\">https://dotinstall.com/lessons/basic_css_v3/31711</a>\r\n\r\n&nbsp;\r\n<h5>■作成物</h5>\r\n&nbsp;\r\n\r\n&nbsp;\r\n<h5>■メモ</h5>\r\nborderで枠を作り、デザインすることができる。\r\n色、幅、スタイルでデザインできる。\r\n個別に項目で指定もできるが、まとめることもできる。\r\n\r\nまとめる場合は、\r\nborder: orange, 4px dotted\r\nのように、borderにスペースで区切って、\r\ncolor width styleの順に指定する。\r\n\r\n右だけ、左だけの枠のみ変更するといった指定ものできる。\r\nborder-top\r\nborder-bottom\r\nborder-right\r\nborder-left\r\n<pre class=\"lang:css decode:true \" title=\"css\">/*\r\n boder\r\n  boder-color:枠の色\r\n  boder-width:枠の幅(太さのイメージ)\r\n  boder-style:種類\r\n    solid:実線\r\n    botted:点線\r\n    dashed:破線\r\n    double:二重線\r\n    inset:立体的に見せる\r\n    outset:同上(あんまり違いが分からん)\r\n */\r\n\r\ndiv {\r\n  /* 個別指定した場合 */\r\n  /* border-color: orange;\r\n  border-width: 4px;\r\n  border-style: double; */\r\n\r\n  /* まとめた場合 */\r\n  /* border: orange 4px dotted; */\r\n\r\n  /* それぞれの枠に設定する */\r\n  border-top: orange 1px solid;\r\n  border-bottom: pink 2px dotted;\r\n  border-right: blue 8px inset;\r\n  border-left: violet 8px outset;\r\n\r\n  /* ちょっとわかりにくいので枠の幅を半分に */\r\n  width: 50%;\r\n\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;div&gt;Element&lt;/div&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #11(ドットインストール)','','inherit','closed','closed','','316-revision-v1','','','2017-12-17 22:59:36','2017-12-17 13:59:36','',316,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/316-revision-v1/',0,'revision','',0),(318,1,'2017-12-17 23:00:37','2017-12-17 14:00:37','<h4>#11 borderで境界線のスタイルを変えよう</h4>\r\n<h5>■動画</h5>\r\n<a href=\"https://dotinstall.com/lessons/basic_css_v3/31711\">https://dotinstall.com/lessons/basic_css_v3/31711</a>\r\n\r\n&nbsp;\r\n<h5>■作成物</h5>\r\n<a href=\"http://www.tmotoki.net/static/dot_install/02_css/11/\">http://www.tmotoki.net/static/dot_install/02_css/11/</a>\r\n\r\n&nbsp;\r\n<h5>■メモ</h5>\r\nborderで枠を作り、デザインすることができる。\r\n色、幅、スタイルでデザインできる。\r\n個別に項目で指定もできるが、まとめることもできる。\r\n\r\nまとめる場合は、\r\nborder: orange, 4px dotted\r\nのように、borderにスペースで区切って、\r\ncolor width styleの順に指定する。\r\n\r\n右だけ、左だけの枠のみ変更するといった指定ものできる。\r\nborder-top\r\nborder-bottom\r\nborder-right\r\nborder-left\r\n<pre class=\"lang:css decode:true \" title=\"css\">/*\r\n boder\r\n  boder-color:枠の色\r\n  boder-width:枠の幅(太さのイメージ)\r\n  boder-style:種類\r\n    solid:実線\r\n    botted:点線\r\n    dashed:破線\r\n    double:二重線\r\n    inset:立体的に見せる\r\n    outset:同上(あんまり違いが分からん)\r\n */\r\n\r\ndiv {\r\n  /* 個別指定した場合 */\r\n  /* border-color: orange;\r\n  border-width: 4px;\r\n  border-style: double; */\r\n\r\n  /* まとめた場合 */\r\n  /* border: orange 4px dotted; */\r\n\r\n  /* それぞれの枠に設定する */\r\n  border-top: orange 1px solid;\r\n  border-bottom: pink 2px dotted;\r\n  border-right: blue 8px inset;\r\n  border-left: violet 8px outset;\r\n\r\n  /* ちょっとわかりにくいので枠の幅を半分に */\r\n  width: 50%;\r\n\r\n}</pre>\r\n<pre class=\"lang:xhtml decode:true \" title=\"html\">&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"ja\"&gt;\r\n	&lt;head&gt;\r\n		&lt;meta charset=\"utf8\"&gt;\r\n		&lt;title&gt;CSS Practice&lt;/title&gt;\r\n	&lt;/head&gt;\r\n	&lt;link rel=\"stylesheet\" href=\"default.css\"&gt;\r\n	&lt;body&gt;\r\n		&lt;div&gt;Element&lt;/div&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n&nbsp;','CSS #11(ドットインストール)','','inherit','closed','closed','','316-revision-v1','','','2017-12-17 23:00:37','2017-12-17 14:00:37','',316,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/316-revision-v1/',0,'revision','',0),(319,1,'2017-12-19 21:35:28','2017-12-19 12:35:28','このサイトはAWS EC2の最安値プランである、\r\nt2.microでやってるのですが、\r\nこのところ頻繁にデータベースアクセスエラーや、\r\nサーバそのものが落ちたりすることがあります。\r\n\r\n&nbsp;\r\n<h3>■調査</h3>\r\nどうやらメモリ不足が原因であることが多いようです。\r\n<pre class=\"lang:sh decode:true \">$ free\r\n             total       used       free     shared    buffers     cached\r\nMem:       1017292     479072     538220        148      15464     158588\r\n-/+ buffers/cache:     305020     712272\r\nSwap:            0          0          0\r\n</pre>\r\n&nbsp;\r\n\r\n再起動直後で何にもしてないのに、\r\nすでに500Mbyteくらいつかっている。\r\nこれはいけない・・。\r\n\r\nApacheとWordpressくらいしか動かしてないのに、\r\nWordPressで結構重いのかな？topコマンドでみてみます。\r\n<pre class=\"lang:sh decode:true\">$top\r\ntop - 12:01:29 up 15 min,  1 user,  load average: 0.00, 0.00, 0.00\r\nTasks:  88 total,   1 running,  87 sleeping,   0 stopped,   0 zombie\r\nCpu(s):  9.7%us,  0.3%sy,  0.0%ni, 90.0%id,  0.0%wa,  0.0%hi,  0.0%si,  0.0%st\r\nMem:   1017292k total,   848764k used,   168528k free,    17316k buffers\r\nSwap:        0k total,        0k used,        0k free,   162212k cached\r\n\r\n  PID USER      PR  NI  VIRT  RES  SHR S %CPU %MEM    TIME+  COMMAND\r\n 2822 apache    20   0  441m  83m  15m S 10.0  8.4   0:01.53 httpd\r\n 3287 ec2-user  20   0 15316 2212 1924 R  0.3  0.2   0:00.04 top\r\n    1 root      20   0 19640 2524 2212 S  0.0  0.2   0:00.89 init\r\n    2 root      20   0     0    0    0 S  0.0  0.0   0:00.00 kthreadd\r\n</pre>\r\n<a href=\"https://qiita.com/k0kubun/items/7368c323d90f24a00c2f\">転用元</a>\r\n<ul>\r\n 	<li><strong>NI</strong>: Nice value。相対優先度。0が基準で、負だと優先度が高く、正だと優先度が低い。</li>\r\n 	<li><strong>VIRT</strong>: Virtual Image。確保された仮想メモリ全て。スワップしたメモリ使用量を含む。</li>\r\n 	<li><strong>RES</strong>: Resident size。 スワップしていない、使用した物理メモリのサイズ。</li>\r\n 	<li><strong>SHR</strong>: Shared Mem size。 他のプロセスと共有される可能性のあるメモリのサイズ。</li>\r\n</ul>\r\nhttpdがApacheです。\r\nMySQLはとらえられませんでしたが、\r\n瞬間的ではあるけども10MByte～50Mbyteとるみたいです。\r\nそら厳しいわ。\r\n\r\n&nbsp;\r\n<h3>■対策</h3>\r\nというわけで対策してみます。\r\nさきほどのfreeコマンドでSWAPが0だったので、\r\n足りなかった場合はHDDをつかって退避する仕組みで、\r\nなんとかならないかやってみます。\r\n\r\n<a href=\"http://e-words.jp/w/%E3%82%B9%E3%83%AF%E3%83%83%E3%83%97.html\">スワップ 【 swap 】 メモリスワップ / memory swap</a>\r\n<ol>\r\n 	<li>\r\n<h5>スワップファイルを作成する</h5>\r\n多すぎる気もしますが、1GBのスワップファイルを作成してみます。\r\nMySQLが仮想メモリを600MBくらい掴んでるのを見たので保険。\r\n<pre class=\"lang:sh decode:true \">$ sudo dd if=/dev/zero of=/swapfile1 bs=1M count=1024\r\n1024+0 records in\r\n1024+0 records out\r\n1073741824 bytes (1.1 GB) copied, 15.4753 s, 69.4 MB/s\r\n</pre>\r\n</li>\r\n 	<li>\r\n<h5>ファイルが作成されたことを確認する</h5>\r\n<pre class=\"lang:sh decode:true \">$ ll /swapfile1\r\n-rw-r--r-- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\r\n0で埋め尽くされた1GBのファイルができあがっています。</li>\r\n 	<li>\r\n<h5>スワップファイルのパーミッションを600に変更</h5>\r\n<pre class=\"lang:sh decode:true\">$sudo chmod 600 /swapfile1\r\n$ ll /swapfile1\r\n-rw------- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\r\n管理者のみ書き込みと読み取りの権限があるように変更します。\r\nデフォルトではゲストや他のユーザも読めるようになっていました。</li>\r\n 	<li>\r\n<h5>作成したスワップファイルをswap領域用にフォーマット</h5>\r\n<pre class=\"lang:sh decode:true\">$ sudo mkswap /swapfile1\r\nSetting up swapspace version 1, size = 1048572 KiB\r\nno label, UUID=1c28b113-43a0-490e-9f2e-c40202218de4</pre>\r\n</li>\r\n 	<li>\r\n<h5>スワップファイルを有効化する</h5>\r\n<pre class=\"lang:sh decode:true \">$ sudo swapon -s\r\n$ sudo swapon /swapfile1\r\n$ sudo swapon -s\r\nFilename                                Type            Size    Used    Priority\r\n/swapfile1                              file    1048572 0       -1\r\n</pre>\r\nswapon -s は 有効なスワップのリスト表示のようですね。\r\n2回目のコマンドで有効化していることがわかります。\r\n\r\nさらに本当に増えているかfreeコマンドでみておきます。\r\n<pre class=\"lang:sh decode:true \">$ free\r\n             total       used       free     shared    buffers     cached\r\nMem:       1017292     934580      82712        148      16388     255976\r\n-/+ buffers/cache:     662216     355076\r\nSwap:      1048572          0    1048572</pre>\r\nswapの行のfree(空き)に1GBが追加されていることが分かります。</li>\r\n 	<li>\r\n<h5>再起動後も設定されているようにする</h5>\r\nこのままではOSを再起動すると、もう一回同じ設定をしないといけないです。\r\nその為下記設定を変更します。\r\n<pre class=\"lang:sh decode:true \">$ sudo cp -p /etc/fstab /etc/fstab.ORG\r\n$ cat /etc/fstab\r\n#\r\nLABEL=/     /           ext4    defaults,noatime  1   1\r\ntmpfs       /dev/shm    tmpfs   defaults        0   0\r\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\r\nsysfs       /sys        sysfs   defaults        0   0\r\nproc        /proc       proc    defaults        0   0</pre>\r\nとりあえずオリジナルをバックアップして、\r\n中身を確認すると、このような感じになっています。\r\n<pre class=\"lang:sh decode:true \">$ sudo vi /etc/fstab\r\n$ cat /etc/fstab\r\n#\r\nLABEL=/     /           ext4    defaults,noatime  1   1\r\ntmpfs       /dev/shm    tmpfs   defaults        0   0\r\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\r\nsysfs       /sys        sysfs   defaults        0   0\r\nproc        /proc       proc    defaults        0   0\r\n/swapfile1  swap        swap    defaults        0   0</pre>\r\n私は直接編集して、\r\n/swapfile1 swap swap defaults 0 0\r\nを一番下に追加しました。</li>\r\n</ol>\r\n&nbsp;\r\n\r\nこれでいったん様子見です。\r\n\r\nこの方式だと挙動が重たいのは否めないので、\r\n根本対策としてはプラン変更でのスケールアウトですが、\r\nお金ないので無理（笑）','MySQLが頻繁に落ちる場合の対策','','publish','open','open','','mysql%e3%81%8c%e9%a0%bb%e7%b9%81%e3%81%ab%e8%90%bd%e3%81%a1%e3%82%8b%e5%a0%b4%e5%90%88%e3%81%ae%e5%af%be%e7%ad%96','','','2017-12-19 23:48:46','2017-12-19 14:48:46','',0,'http://www.tmotoki.net/?p=319',0,'post','',0),(320,1,'2017-12-19 21:35:28','2017-12-19 12:35:28','このところ頻繁にデータベースアクセスエラーや、\r\nサーバそのものが落ちたりすることがあります。\r\n\r\n&nbsp;\r\n\r\nこのサイトはAWS EC2の最安値プランである、\r\nt2.microでやってるのですが、\r\nどうやらメモリ不足が原因であることが多いようです。\r\n<pre class=\"lang:sh decode:true\">$ free\r\n             total       used       free     shared    buffers     cached\r\nMem:       1017292     479072     538220        148      15464     158588\r\n-/+ buffers/cache:     305020     712272\r\nSwap:            0          0          0\r\n</pre>\r\n&nbsp;\r\n\r\n再起動直後で何にもしてないのに、\r\nすでに500Mbyteくらいつかっている。\r\nこれはいけない・・。\r\n\r\nApacheとWordpressくらいしか動かしてないのに、\r\nWordPressで結構重いのかな？topコマンドでみてみます。\r\n<pre class=\"lang:sh decode:true\">$top\r\ntop - 12:01:29 up 15 min,  1 user,  load average: 0.00, 0.00, 0.00\r\nTasks:  88 total,   1 running,  87 sleeping,   0 stopped,   0 zombie\r\nCpu(s):  9.7%us,  0.3%sy,  0.0%ni, 90.0%id,  0.0%wa,  0.0%hi,  0.0%si,  0.0%st\r\nMem:   1017292k total,   848764k used,   168528k free,    17316k buffers\r\nSwap:        0k total,        0k used,        0k free,   162212k cached\r\n\r\n  PID USER      PR  NI  VIRT  RES  SHR S %CPU %MEM    TIME+  COMMAND\r\n 2822 apache    20   0  441m  83m  15m S 10.0  8.4   0:01.53 httpd\r\n 3287 ec2-user  20   0 15316 2212 1924 R  0.3  0.2   0:00.04 top\r\n    1 root      20   0 19640 2524 2212 S  0.0  0.2   0:00.89 init\r\n    2 root      20   0     0    0    0 S  0.0  0.0   0:00.00 kthreadd\r\n</pre>\r\n<a href=\"https://qiita.com/k0kubun/items/7368c323d90f24a00c2f\">転用元</a>\r\n<ul>\r\n 	<li><strong>NI</strong>: Nice value。相対優先度。0が基準で、負だと優先度が高く、正だと優先度が低い。</li>\r\n 	<li><strong>VIRT</strong>: Virtual Image。確保された仮想メモリ全て。スワップしたメモリ使用量を含む。</li>\r\n 	<li><strong>RES</strong>: Resident size。 スワップしていない、使用した物理メモリのサイズ。</li>\r\n 	<li><strong>SHR</strong>: Shared Mem size。 他のプロセスと共有される可能性のあるメモリのサイズ。</li>\r\n</ul>\r\nhttpdがApacheです。\r\nMySQLはとらえられませんでしたが、\r\n瞬間的ではあるけども10MByte～50Mbyteとるみたいです。\r\nそら厳しいわ。\r\n\r\nというわけで対策してみます。\r\nさきほどのfreeコマンドでSWAPが0だったので、\r\n足りなかった場合はHDDをつかって退避する仕組みで、\r\nなんとかならないかやってみます。\r\n\r\n<a href=\"http://e-words.jp/w/%E3%82%B9%E3%83%AF%E3%83%83%E3%83%97.html\">スワップ 【 swap 】 メモリスワップ / memory swap</a>\r\n<ol>\r\n 	<li>スワップファイルを作成する\r\n\r\n多すぎる気もしますが、1GBのスワップファイルを作成してみます。\r\n<pre class=\"lang:sh decode:true \">$ sudo dd if=/dev/zero of=/swapfile1 bs=1M count=1024\r\n1024+0 records in\r\n1024+0 records out\r\n1073741824 bytes (1.1 GB) copied, 15.4753 s, 69.4 MB/s\r\n</pre>\r\n</li>\r\n 	<li>ファイルが作成されたことを確認する\r\n<pre class=\"lang:sh decode:true \">$ ll /swapfile1\r\n-rw-r--r-- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\r\n0で埋め尽くされた1GBのファイルができあがっています。</li>\r\n 	<li>スワップファイルのパーミッションを600に変更\r\n<pre class=\"lang:sh decode:true\">$sudo chmod 600 /swapfile1\r\n$ ll /swapfile1\r\n-rw------- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\r\n管理者に書き込みと読み取りの権限を付与しています。</li>\r\n 	<li>作成したスワップファイルをswap領域用にフォーマット\r\n<pre class=\"lang:sh decode:true\">$ sudo mkswap /swapfile1\r\nSetting up swapspace version 1, size = 1048572 KiB\r\nno label, UUID=1c28b113-43a0-490e-9f2e-c40202218de4</pre>\r\n</li>\r\n 	<li>スワップファイルを有効化する\r\n<pre class=\"lang:sh decode:true \">$ sudo swapon -s\r\n$ sudo swapon /swapfile1\r\n$ sudo swapon -s\r\nFilename                                Type            Size    Used    Priority\r\n/swapfile1                              file    1048572 0       -1\r\n</pre>\r\nswapon -s は スワップファイルのリスト表示のようですね。\r\n2回目のコマンドで有効化していることがわかります。\r\n\r\nさらに本当に増えているかfreeコマンドでみておきます。\r\n<pre class=\"lang:sh decode:true \">$ free\r\n             total       used       free     shared    buffers     cached\r\nMem:       1017292     934580      82712        148      16388     255976\r\n-/+ buffers/cache:     662216     355076\r\nSwap:      1048572          0    1048572</pre>\r\nswapの行のfree(空き)に1GBが追加されていることが分かります。</li>\r\n 	<li>再起動後も設定されているようにする\r\nこのままではOSを再起動すると、もう一回同じ設定をしないといけないです。\r\nその為下記設定を変更します。\r\n<pre class=\"lang:sh decode:true\">$ sudo cp -p /etc/fstab /etc/fstab.ORG\r\n$ cat /etc/fstab\r\n#\r\nLABEL=/     /           ext4    defaults,noatime  1   1\r\ntmpfs       /dev/shm    tmpfs   defaults        0   0\r\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\r\nsysfs       /sys        sysfs   defaults        0   0\r\nproc        /proc       proc    defaults        0   0</pre>\r\nとりあえずオリジナルをバックアップして、\r\n中身を確認すると、このような感じになっています。\r\n<pre class=\"lang:sh decode:true \">$ sudo vi /etc/fstab\r\n$ cat /etc/fstab\r\n#\r\nLABEL=/     /           ext4    defaults,noatime  1   1\r\ntmpfs       /dev/shm    tmpfs   defaults        0   0\r\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\r\nsysfs       /sys        sysfs   defaults        0   0\r\nproc        /proc       proc    defaults        0   0\r\n/swapfile1  swap        swap    defaults        0   0</pre>\r\n私は直接編集して、\r\n/swapfile1 swap swap defaults 0 0\r\nを一番下に追加しました。</li>\r\n</ol>\r\n&nbsp;\r\n\r\nこれでいったん様子見です。','MySQLが頻繁に落ちる場合の対策','','inherit','closed','closed','','319-revision-v1','','','2017-12-19 21:35:28','2017-12-19 12:35:28','',319,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/319-revision-v1/',0,'revision','',0),(321,1,'2017-12-19 21:49:05','2017-12-19 12:49:05','このサイトはAWS EC2の最安値プランである、\nt2.microでやってるのですが、\nこのところ頻繁にデータベースアクセスエラーや、\nサーバそのものが落ちたりすることがあります。\n\n&nbsp;\n\nどうやらメモリ不足が原因であることが多いようです。\n<pre class=\"lang:sh decode:true \">$ free\n             total       used       free     shared    buffers     cached\nMem:       1017292     479072     538220        148      15464     158588\n-/+ buffers/cache:     305020     712272\nSwap:            0          0          0\n</pre>\n&nbsp;\n\n再起動直後で何にもしてないのに、\nすでに500Mbyteくらいつかっている。\nこれはいけない・・。\n\nApacheとWordpressくらいしか動かしてないのに、\nWordPressで結構重いのかな？topコマンドでみてみます。\n<pre class=\"lang:sh decode:true\">$top\ntop - 12:01:29 up 15 min,  1 user,  load average: 0.00, 0.00, 0.00\nTasks:  88 total,   1 running,  87 sleeping,   0 stopped,   0 zombie\nCpu(s):  9.7%us,  0.3%sy,  0.0%ni, 90.0%id,  0.0%wa,  0.0%hi,  0.0%si,  0.0%st\nMem:   1017292k total,   848764k used,   168528k free,    17316k buffers\nSwap:        0k total,        0k used,        0k free,   162212k cached\n\n  PID USER      PR  NI  VIRT  RES  SHR S %CPU %MEM    TIME+  COMMAND\n 2822 apache    20   0  441m  83m  15m S 10.0  8.4   0:01.53 httpd\n 3287 ec2-user  20   0 15316 2212 1924 R  0.3  0.2   0:00.04 top\n    1 root      20   0 19640 2524 2212 S  0.0  0.2   0:00.89 init\n    2 root      20   0     0    0    0 S  0.0  0.0   0:00.00 kthreadd\n</pre>\n<a href=\"https://qiita.com/k0kubun/items/7368c323d90f24a00c2f\">転用元</a>\n<ul>\n 	<li><strong>NI</strong>: Nice value。相対優先度。0が基準で、負だと優先度が高く、正だと優先度が低い。</li>\n 	<li><strong>VIRT</strong>: Virtual Image。確保された仮想メモリ全て。スワップしたメモリ使用量を含む。</li>\n 	<li><strong>RES</strong>: Resident size。 スワップしていない、使用した物理メモリのサイズ。</li>\n 	<li><strong>SHR</strong>: Shared Mem size。 他のプロセスと共有される可能性のあるメモリのサイズ。</li>\n</ul>\nhttpdがApacheです。\nMySQLはとらえられませんでしたが、\n瞬間的ではあるけども10MByte～50Mbyteとるみたいです。\nそら厳しいわ。\n\nというわけで対策してみます。\nさきほどのfreeコマンドでSWAPが0だったので、\n足りなかった場合はHDDをつかって退避する仕組みで、\nなんとかならないかやってみます。\n\n<a href=\"http://e-words.jp/w/%E3%82%B9%E3%83%AF%E3%83%83%E3%83%97.html\">スワップ 【 swap 】 メモリスワップ / memory swap</a>\n<ol>\n 	<li>\n<h5>スワップファイルを作成する</h5>\n多すぎる気もしますが、1GBのスワップファイルを作成してみます。\nMySQLが仮想メモリを600MBくらい掴んでるのを見たので保険。\n<pre class=\"lang:sh decode:true \">$ sudo dd if=/dev/zero of=/swapfile1 bs=1M count=1024\n1024+0 records in\n1024+0 records out\n1073741824 bytes (1.1 GB) copied, 15.4753 s, 69.4 MB/s\n</pre>\n</li>\n 	<li>\n<h5>ファイルが作成されたことを確認する</h5>\n<pre class=\"lang:sh decode:true \">$ ll /swapfile1\n-rw-r--r-- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\n0で埋め尽くされた1GBのファイルができあがっています。</li>\n 	<li>\n<h5>スワップファイルのパーミッションを600に変更</h5>\n<pre class=\"lang:sh decode:true\">$sudo chmod 600 /swapfile1\n$ ll /swapfile1\n-rw------- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\n管理者のみ書き込みと読み取りの権限があるように変更します。\nデフォルトではゲストや他のユーザも読めるようになっていました。</li>\n 	<li>\n<h5>作成したスワップファイルをswap領域用にフォーマット</h5>\n<pre class=\"lang:sh decode:true\">$ sudo mkswap /swapfile1\nSetting up swapspace version 1, size = 1048572 KiB\nno label, UUID=1c28b113-43a0-490e-9f2e-c40202218de4</pre>\n</li>\n 	<li>\n<h5>スワップファイルを有効化する</h5>\n<pre class=\"lang:sh decode:true \">$ sudo swapon -s\n$ sudo swapon /swapfile1\n$ sudo swapon -s\nFilename                                Type            Size    Used    Priority\n/swapfile1                              file    1048572 0       -1\n</pre>\nswapon -s は 有効なスワップのリスト表示のようですね。\n2回目のコマンドで有効化していることがわかります。\n\nさらに本当に増えているかfreeコマンドでみておきます。\n<pre class=\"lang:sh decode:true \">$ free\n             total       used       free     shared    buffers     cached\nMem:       1017292     934580      82712        148      16388     255976\n-/+ buffers/cache:     662216     355076\nSwap:      1048572          0    1048572</pre>\nswapの行のfree(空き)に1GBが追加されていることが分かります。</li>\n 	<li>\n<h5>再起動後も設定されているようにする</h5>\nこのままではOSを再起動すると、もう一回同じ設定をしないといけないです。\nその為下記設定を変更します。\n<pre class=\"lang:sh decode:true \">$ sudo cp -p /etc/fstab /etc/fstab.ORG\n$ cat /etc/fstab\n#\nLABEL=/     /           ext4    defaults,noatime  1   1\ntmpfs       /dev/shm    tmpfs   defaults        0   0\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\nsysfs       /sys        sysfs   defaults        0   0\nproc        /proc       proc    defaults        0   0</pre>\nとりあえずオリジナルをバックアップして、\n中身を確認すると、このような感じになっています。\n<pre class=\"lang:sh decode:true \">$ sudo vi /etc/fstab\n$ cat /etc/fstab\n#\nLABEL=/     /           ext4    defaults,noatime  1   1\ntmpfs       /dev/shm    tmpfs   defaults        0   0\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\nsysfs       /sys        sysfs   defaults        0   0\nproc        /proc       proc    defaults        0   0\n/swapfile1  swap        swap    defaults        0   0</pre>\n私は直接編集して、\n/swapfile1 swap swap defaults 0 0\nを一番下に追加しました。</li>\n</ol>\n&nbsp;\n\nこれでいったん様子見です。\nこの方式だと挙動が重たいのは否めないので、\n根本対策としてはプラン変更でのスケールアウトですが、','MySQLが頻繁に落ちる場合の対策','','inherit','closed','closed','','319-autosave-v1','','','2017-12-19 21:49:05','2017-12-19 12:49:05','',319,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/319-autosave-v1/',0,'revision','',0),(322,1,'2017-12-19 21:37:02','2017-12-19 12:37:02','このところ頻繁にデータベースアクセスエラーや、\r\nサーバそのものが落ちたりすることがあります。\r\n\r\n&nbsp;\r\n\r\nこのサイトはAWS EC2の最安値プランである、\r\nt2.microでやってるのですが、\r\nどうやらメモリ不足が原因であることが多いようです。\r\n<pre class=\"lang:sh decode:true\">$ free\r\n             total       used       free     shared    buffers     cached\r\nMem:       1017292     479072     538220        148      15464     158588\r\n-/+ buffers/cache:     305020     712272\r\nSwap:            0          0          0\r\n</pre>\r\n&nbsp;\r\n\r\n再起動直後で何にもしてないのに、\r\nすでに500Mbyteくらいつかっている。\r\nこれはいけない・・。\r\n\r\nApacheとWordpressくらいしか動かしてないのに、\r\nWordPressで結構重いのかな？topコマンドでみてみます。\r\n<pre class=\"lang:sh decode:true\">$top\r\ntop - 12:01:29 up 15 min,  1 user,  load average: 0.00, 0.00, 0.00\r\nTasks:  88 total,   1 running,  87 sleeping,   0 stopped,   0 zombie\r\nCpu(s):  9.7%us,  0.3%sy,  0.0%ni, 90.0%id,  0.0%wa,  0.0%hi,  0.0%si,  0.0%st\r\nMem:   1017292k total,   848764k used,   168528k free,    17316k buffers\r\nSwap:        0k total,        0k used,        0k free,   162212k cached\r\n\r\n  PID USER      PR  NI  VIRT  RES  SHR S %CPU %MEM    TIME+  COMMAND\r\n 2822 apache    20   0  441m  83m  15m S 10.0  8.4   0:01.53 httpd\r\n 3287 ec2-user  20   0 15316 2212 1924 R  0.3  0.2   0:00.04 top\r\n    1 root      20   0 19640 2524 2212 S  0.0  0.2   0:00.89 init\r\n    2 root      20   0     0    0    0 S  0.0  0.0   0:00.00 kthreadd\r\n</pre>\r\n<a href=\"https://qiita.com/k0kubun/items/7368c323d90f24a00c2f\">転用元</a>\r\n<ul>\r\n 	<li><strong>NI</strong>: Nice value。相対優先度。0が基準で、負だと優先度が高く、正だと優先度が低い。</li>\r\n 	<li><strong>VIRT</strong>: Virtual Image。確保された仮想メモリ全て。スワップしたメモリ使用量を含む。</li>\r\n 	<li><strong>RES</strong>: Resident size。 スワップしていない、使用した物理メモリのサイズ。</li>\r\n 	<li><strong>SHR</strong>: Shared Mem size。 他のプロセスと共有される可能性のあるメモリのサイズ。</li>\r\n</ul>\r\nhttpdがApacheです。\r\nMySQLはとらえられませんでしたが、\r\n瞬間的ではあるけども10MByte～50Mbyteとるみたいです。\r\nそら厳しいわ。\r\n\r\nというわけで対策してみます。\r\nさきほどのfreeコマンドでSWAPが0だったので、\r\n足りなかった場合はHDDをつかって退避する仕組みで、\r\nなんとかならないかやってみます。\r\n\r\n<a href=\"http://e-words.jp/w/%E3%82%B9%E3%83%AF%E3%83%83%E3%83%97.html\">スワップ 【 swap 】 メモリスワップ / memory swap</a>\r\n<ol>\r\n 	<li>スワップファイルを作成する多すぎる気もしますが、1GBのスワップファイルを作成してみます。\r\nMySQLが仮想メモリを600MBくらい掴んでるのを見たので保険。\r\n<pre class=\"lang:sh decode:true \">$ sudo dd if=/dev/zero of=/swapfile1 bs=1M count=1024\r\n1024+0 records in\r\n1024+0 records out\r\n1073741824 bytes (1.1 GB) copied, 15.4753 s, 69.4 MB/s\r\n</pre>\r\n</li>\r\n 	<li>ファイルが作成されたことを確認する\r\n<pre class=\"lang:sh decode:true \">$ ll /swapfile1\r\n-rw-r--r-- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\r\n0で埋め尽くされた1GBのファイルができあがっています。</li>\r\n 	<li>スワップファイルのパーミッションを600に変更\r\n<pre class=\"lang:sh decode:true\">$sudo chmod 600 /swapfile1\r\n$ ll /swapfile1\r\n-rw------- 1 root root 1073741824 Dec 19 12:14 /swapfile1</pre>\r\n管理者に書き込みと読み取りの権限を付与しています。</li>\r\n 	<li>作成したスワップファイルをswap領域用にフォーマット\r\n<pre class=\"lang:sh decode:true\">$ sudo mkswap /swapfile1\r\nSetting up swapspace version 1, size = 1048572 KiB\r\nno label, UUID=1c28b113-43a0-490e-9f2e-c40202218de4</pre>\r\n</li>\r\n 	<li>スワップファイルを有効化する\r\n<pre class=\"lang:sh decode:true \">$ sudo swapon -s\r\n$ sudo swapon /swapfile1\r\n$ sudo swapon -s\r\nFilename                                Type            Size    Used    Priority\r\n/swapfile1                              file    1048572 0       -1\r\n</pre>\r\nswapon -s は スワップファイルのリスト表示のようですね。\r\n2回目のコマンドで有効化していることがわかります。\r\n\r\nさらに本当に増えているかfreeコマンドでみておきます。\r\n<pre class=\"lang:sh decode:true \">$ free\r\n             total       used       free     shared    buffers     cached\r\nMem:       1017292     934580      82712        148      16388     255976\r\n-/+ buffers/cache:     662216     355076\r\nSwap:      1048572          0    1048572</pre>\r\nswapの行のfree(空き)に1GBが追加されていることが分かります。</li>\r\n 	<li>再起動後も設定されているようにする\r\nこのままではOSを再起動すると、もう一回同じ設定をしないといけないです。\r\nその為下記設定を変更します。\r\n<pre class=\"lang:sh decode:true\">$ sudo cp -p /etc/fstab /etc/fstab.ORG\r\n$ cat /etc/fstab\r\n#\r\nLABEL=/     /           ext4    defaults,noatime  1   1\r\ntmpfs       /dev/shm    tmpfs   defaults        0   0\r\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\r\nsysfs       /sys        sysfs   defaults        0   0\r\nproc        /proc       proc    defaults        0   0</pre>\r\nとりあえずオリジナルをバックアップして、\r\n中身を確認すると、このような感じになっています。\r\n<pre class=\"lang:sh decode:true \">$ sudo vi /etc/fstab\r\n$ cat /etc/fstab\r\n#\r\nLABEL=/     /           ext4    defaults,noatime  1   1\r\ntmpfs       /dev/shm    tmpfs   defaults        0   0\r\ndevpts      /dev/pts    devpts  gid=5,mode=620  0   0\r\nsysfs       /sys        sysfs   defaults        0   0\r\nproc        /proc       proc    defaults        0   0\r\n/swapfile1  swap        swap    defaults        0   0</pre>\r\n私は直接編集して、\r\n/swapfile1 swap swap defaults 0 0\r\nを一番下に追加しました。</li>\r\n</ol>\r\n&nbsp;\r\n\r\nこれでいったん様子見です。','MySQLが頻繁に落ちる場合の対策','','inherit','closed','closed','','319-revision-v1','','','2017-12-19 21:37:02','2017-12-19 12:37:02','',319,'http://www.tmotoki.net/%e6%9c%aa%e5%88%86%e9%a1%9e/319-revision-v1/',0,'revisi